{
  "expo": {
    "name": "Agent Studio",
    "slug": "agent-studio",
    "version": "1.0.0",
    "orientation": "portrait",
    "icon": "./assets/images/icon.png",
    "scheme": "agent-studio",
    "userInterfaceStyle": "automatic",
    "newArchEnabled": true,
    "splash": {
      "image": "./assets/images/icon.png",
      "resizeMode": "contain",
      "backgroundColor": "#ffffff"
    },
    "ios": {
      "supportsTablet": false
    },
    "android": {},
    "web": {
      "favicon": "./assets/images/icon.png"
    },
    "plugins": [
      [
        "expo-router",
        {
          "origin": "https://replit.com/"
        }
      ],
      "expo-font",
      "expo-web-browser"
    ],
    "experiments": {
      "typedRoutes": true,
      "reactCompiler": true
    }
  }
}

import {
  Inter_400Regular,
  Inter_500Medium,
  Inter_600SemiBold,
  Inter_700Bold,
  useFonts,
} from "@expo-google-fonts/inter";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { StatusBar } from "expo-status-bar";
import { Stack } from "expo-router";
import * as SplashScreen from "expo-splash-screen";
import * as SystemUI from "expo-system-ui";
import React, { useEffect } from "react";
import { GestureHandlerRootView } from "react-native-gesture-handler";
import { KeyboardProvider } from "react-native-keyboard-controller";
import { SafeAreaProvider } from "react-native-safe-area-context";

import { ErrorBoundary } from "@/components/ErrorBoundary";
import { StudioProvider } from "@/contexts/StudioContext";

SplashScreen.preventAutoHideAsync();
SystemUI.setBackgroundColorAsync("#0a0b18").catch(() => {});

const queryClient = new QueryClient();

function RootLayoutNav() {
  return (
    <Stack
      screenOptions={{
        headerShown: false,
        contentStyle: { backgroundColor: "#0a0b18" },
        animation: "slide_from_right",
      }}
    >
      <Stack.Screen name="(tabs)" />
      <Stack.Screen name="projects" />
      <Stack.Screen name="agents" />
      <Stack.Screen name="training" />
      <Stack.Screen name="new-build" options={{ presentation: "modal" }} />
      <Stack.Screen name="build/[id]" />
    </Stack>
  );
}

export default function RootLayout() {
  const [fontsLoaded, fontError] = useFonts({
    Inter_400Regular,
    Inter_500Medium,
    Inter_600SemiBold,
    Inter_700Bold,
  });

  useEffect(() => {
    if (fontsLoaded || fontError) {
      SplashScreen.hideAsync();
    }
  }, [fontsLoaded, fontError]);

  if (!fontsLoaded && !fontError) return null;

  return (
    <SafeAreaProvider>
      <ErrorBoundary>
        <QueryClientProvider client={queryClient}>
          <GestureHandlerRootView style={{ flex: 1, backgroundColor: "#0a0b18" }}>
            <KeyboardProvider>
              <StudioProvider>
                <StatusBar style="light" />
                <RootLayoutNav />
              </StudioProvider>
            </KeyboardProvider>
          </GestureHandlerRootView>
        </QueryClientProvider>
      </ErrorBoundary>
    </SafeAreaProvider>
  );
}

import { Ionicons } from "@expo/vector-icons";
import { BlurView } from "expo-blur";
import { Tabs } from "expo-router";
import React from "react";
import { Platform, StyleSheet, View, useColorScheme } from "react-native";

import { useColors } from "@/hooks/useColors";

export default function TabLayout() {
  const c = useColors();
  const colorScheme = useColorScheme();
  const isDark = colorScheme === "dark";
  const isWeb = Platform.OS === "web";
  const isIOS = Platform.OS === "ios";

  return (
    <Tabs
      screenOptions={{
        headerShown: false,
        tabBarActiveTintColor: c.violet,
        tabBarInactiveTintColor: c.textMuted,
        tabBarLabelStyle: {
          fontFamily: "Inter_500Medium",
          fontSize: 10,
        },
        tabBarStyle: {
          position: "absolute",
          backgroundColor: isIOS ? "transparent" : c.bgElevated,
          borderTopWidth: 1,
          borderTopColor: c.cardBorderSubtle,
          elevation: 0,
          ...(isWeb ? { height: 84 } : {}),
        },
        tabBarBackground: () =>
          isIOS ? (
            <BlurView
              intensity={80}
              tint={isDark ? "dark" : "dark"}
              style={StyleSheet.absoluteFill}
            />
          ) : isWeb ? (
            <View
              style={[StyleSheet.absoluteFill, { backgroundColor: c.bgElevated }]}
            />
          ) : null,
      }}
    >
      <Tabs.Screen
        name="index"
        options={{
          title: "Home",
          tabBarIcon: ({ color }) => (
            <Ionicons name="grid-outline" size={22} color={color} />
          ),
        }}
      />
      <Tabs.Screen
        name="studio"
        options={{
          title: "Studio",
          tabBarIcon: ({ color }) => (
            <Ionicons name="flash-outline" size={22} color={color} />
          ),
        }}
      />
      <Tabs.Screen
        name="memory"
        options={{
          title: "Memory",
          tabBarIcon: ({ color }) => (
            <Ionicons name="ellipse-outline" size={22} color={color} />
          ),
        }}
      />
      <Tabs.Screen
        name="library"
        options={{
          title: "Library",
          tabBarIcon: ({ color }) => (
            <Ionicons name="book-outline" size={22} color={color} />
          ),
        }}
      />
      <Tabs.Screen
        name="settings"
        options={{
          title: "Settings",
          tabBarIcon: ({ color }) => (
            <Ionicons name="settings-outline" size={22} color={color} />
          ),
        }}
      />
    </Tabs>
  );
}

import { Ionicons, MaterialCommunityIcons } from "@expo/vector-icons";
import { useRouter } from "expo-router";
import React, { useState } from "react";
import {
  ActivityIndicator,
  Alert,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { Card } from "@/components/Card";
import { PipelinePreview } from "@/components/PipelinePreview";
import { Pill } from "@/components/Pill";
import { PrimaryButton } from "@/components/PrimaryButton";
import { ScreenHeader } from "@/components/ScreenHeader";
import { SideMenu } from "@/components/SideMenu";
import { StatTile } from "@/components/StatTile";
import { useStudio } from "@/contexts/StudioContext";
import { useColors } from "@/hooks/useColors";
import { pingPollinations } from "@/lib/pollinations";
import { PRESET_BUILDS } from "@/lib/seed";
import type { HealthCheck, HealthName, UpgradeProposal } from "@/lib/types";

export default function HomeScreen() {
  const c = useColors();
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const {
    projects,
    memories,
    settings,
    startBuild,
    analyzeForUpgrades,
    applyUpgrade,
    rollbackUpgrade,
    dismissProposal,
    proposals,
    snapshots,
    activeBuildId,
  } = useStudio();
  const [menuOpen, setMenuOpen] = useState(false);
  const [systemTestRunning, setSystemTestRunning] = useState(false);
  const [systemTestLog, setSystemTestLog] = useState<HealthCheck[]>([]);
  const [analyzing, setAnalyzing] = useState(false);
  const [applyingId, setApplyingId] = useState<string | null>(null);
  const [confirmingId, setConfirmingId] = useState<string | null>(null);

  const inProgress = projects.find((p) => p.status === "building");
  const liveProposals: UpgradeProposal[] = proposals.filter((p) => !p.applied);
  const recentSnapshot = snapshots[0];

  const runSystemTest = async () => {
    setSystemTestRunning(true);
    const checks: { name: HealthName; label: string }[] = [
      { name: "pollinations", label: "Pollinations AI endpoint reachable" },
      { name: "groq", label: "Groq API (optional) configured" },
      { name: "custom", label: "Custom OpenAI key configured" },
      { name: "proxy", label: "Proxy integration URL set" },
      { name: "auth", label: "API authorization header set" },
      { name: "cache", label: "Device cache (AsyncStorage) writable" },
    ];

    const results: HealthCheck[] = checks.map((c0) => ({
      ...c0,
      state: "checking",
    }));
    setSystemTestLog(results);

    for (let i = 0; i < checks.length; i++) {
      const check = checks[i];
      if (!check) continue;
      let ok = false;
      let detail = "";
      switch (check.name) {
        case "pollinations":
          ok = await pingPollinations();
          detail = ok ? "200 OK" : "unreachable";
          break;
        case "groq":
          ok = settings.groqKey.trim().length > 0;
          detail = ok ? "key present" : "no key set";
          break;
        case "custom":
          ok = settings.customKey.trim().length > 0;
          detail = ok ? "key present" : "no key set";
          break;
        case "proxy":
          ok = settings.proxyUrl.trim().length > 0;
          detail = ok ? "URL present" : "no URL set";
          break;
        case "auth":
          ok = settings.authorizationHeader.trim().length > 0;
          detail = ok ? "header present" : "no header set";
          break;
        case "cache":
          ok = true;
          detail = "writable";
          break;
      }
      results[i] = { ...check, state: ok ? "ok" : "fail", detail };
      setSystemTestLog([...results]);
      await new Promise((r) => setTimeout(r, 250));
    }

    setSystemTestRunning(false);
  };

  const analyzeInfra = async () => {
    setAnalyzing(true);
    try {
      await analyzeForUpgrades();
    } catch (e) {
      const msg = e instanceof Error ? e.message : "failed";
      Alert.alert("Analysis failed", msg);
    } finally {
      setAnalyzing(false);
    }
  };

  const onApply = async (p: UpgradeProposal) => {
    // Inline two-step confirm — works reliably on web & native (no Alert chains).
    if (settings.requireApprovalForUpgrades && confirmingId !== p.id) {
      setConfirmingId(p.id);
      // Auto-clear confirm prompt after 5s if the user does nothing.
      setTimeout(() => {
        setConfirmingId((cur) => (cur === p.id ? null : cur));
      }, 5000);
      return;
    }
    setConfirmingId(null);
    setApplyingId(p.id);
    const r = await applyUpgrade(p.id);
    setApplyingId(null);
    Alert.alert(r.ok ? "Applied" : "Failed", r.message);
  };

  const onRollback = () => {
    if (!recentSnapshot) return;
    Alert.alert(
      "Roll back upgrade?",
      `Restore: ${recentSnapshot.label}`,
      [
        { text: "Cancel", style: "cancel" },
        {
          text: "Roll back",
          style: "destructive",
          onPress: async () => {
            const r = await rollbackUpgrade(recentSnapshot.id);
            Alert.alert(r.ok ? "Restored" : "Failed", r.message);
          },
        },
      ],
    );
  };

  const usePreset = async (preset: (typeof PRESET_BUILDS)[number]) => {
    const id = await startBuild({
      description: preset.description,
      platform: preset.platform,
      name: preset.title,
    });
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    router.push(`/build/${id}` as any);
  };

  return (
    <View style={{ flex: 1, backgroundColor: c.bg }}>
      <ScreenHeader
        title="Agent Studio"
        showMenu
        onMenuPress={() => setMenuOpen(true)}
      />

      <ScrollView
        contentContainerStyle={{
          padding: 16,
          paddingBottom: insets.bottom + 120,
          gap: 16,
        }}
      >
        {/* Hero */}
        <View>
          <View style={styles.heroRow}>
            <View
              style={[styles.heroIcon, { backgroundColor: c.cardSubtle, borderColor: c.cardBorder }]}
            >
              <Ionicons name="phone-portrait-outline" size={22} color={c.text} />
            </View>
            <View style={{ flex: 1 }}>
              <Text style={[styles.heroTitle, { color: c.text }]}>Agent Studio</Text>
              <Text style={[styles.heroSub, { color: c.textMuted }]}>
                FREE Pollinations AI · 5-agent build pipeline
              </Text>
            </View>
            <Pill label="● READY" tone="green" />
          </View>
        </View>

        {/* Stat tiles */}
        <View style={styles.statRow}>
          <StatTile value="5" label="Active Agents" tone="primary" icon="apps-outline" />
          <StatTile
            value="Pollinations"
            label="FREE AI"
            tone="green"
            icon="sparkles-outline"
          />
          <StatTile value="Ready" label="APK Output" tone="amber" icon="cube-outline" />
        </View>

        {/* Studio System Test */}
        <Card>
          <View style={styles.sectionRow}>
            <Ionicons name="flask-outline" size={18} color={c.cyan} />
            <Text style={[styles.sectionTitle, { color: c.text }]}>
              Studio System Test
            </Text>
          </View>
          <Text style={[styles.sectionDesc, { color: c.textMuted }]}>
            Run 6 automated checks across AI endpoints, database, pipeline config,
            file parser, and cache. Generates a full diagnostic log.
          </Text>
          <PrimaryButton
            label={systemTestRunning ? "Running…" : "Run System Test"}
            icon="play"
            variant="outline"
            onPress={runSystemTest}
            loading={systemTestRunning}
            fullWidth
          />
          {systemTestLog.length > 0 ? (
            <View
              style={[
                styles.logBox,
                { borderColor: c.cardBorder, backgroundColor: c.bgElevated },
              ]}
            >
              {systemTestLog.map((row) => (
                <View key={row.name} style={styles.logRow}>
                  <Text style={{ color: c.textMuted, fontSize: 11, fontFamily: "Inter_500Medium" }}>
                    {row.state === "ok"
                      ? "✓"
                      : row.state === "fail"
                        ? "✗"
                        : row.state === "checking"
                          ? "…"
                          : " "}
                  </Text>
                  <Text
                    style={{
                      flex: 1,
                      color:
                        row.state === "ok"
                          ? c.green
                          : row.state === "fail"
                            ? c.amber
                            : c.textSecondary,
                      fontSize: 12,
                      fontFamily: "Inter_400Regular",
                    }}
                  >
                    {row.label}
                    {row.detail ? (
                      <Text style={{ color: c.textDim }}> · {row.detail}</Text>
                    ) : null}
                  </Text>
                </View>
              ))}
            </View>
          ) : null}
        </Card>

        {/* Resume in-progress build */}
        {inProgress ? (
          <Pressable
            onPress={() =>
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              router.push(`/build/${inProgress.id}` as any)
            }
          >
            <Card style={{ borderColor: c.amberBorder, backgroundColor: c.amberSoft }}>
              <View style={{ flexDirection: "row", alignItems: "center", gap: 10 }}>
                <Ionicons name="play-circle" size={22} color={c.amber} />
                <View style={{ flex: 1 }}>
                  <Text style={{ color: c.amber, fontFamily: "Inter_700Bold", fontSize: 13 }}>
                    Build in progress · tap to open
                  </Text>
                  <Text style={{ color: c.textSecondary, fontFamily: "Inter_500Medium", fontSize: 12, marginTop: 2 }}>
                    {inProgress.name}
                    {activeBuildId === inProgress.id ? "" : " · paused — resume from build screen"}
                  </Text>
                </View>
                <Ionicons name="chevron-forward" size={18} color={c.amber} />
              </View>
            </Card>
          </Pressable>
        ) : null}

        {/* Infrastructure Analysis with self-upgrade proposals */}
        <Card>
          <View style={styles.sectionRow}>
            <Ionicons name="trending-up" size={18} color={c.violet} />
            <Text style={[styles.sectionTitle, { color: c.text }]}>
              Self-Upgrade Auditor
            </Text>
          </View>
          <Text style={[styles.sectionDesc, { color: c.textMuted }]}>
            AI audits your studio config and proposes safety / quality upgrades.{" "}
            <Text style={{ color: c.amber, fontFamily: "Inter_600SemiBold" }}>
              Each apply takes a snapshot you can roll back.
            </Text>
          </Text>
          <PrimaryButton
            label={analyzing ? "Analyzing…" : "Analyze & Propose Upgrades"}
            icon="analytics-outline"
            variant="primary"
            onPress={analyzeInfra}
            loading={analyzing}
            fullWidth
          />

          {liveProposals.length > 0 ? (
            <View style={{ gap: 10, marginTop: 12 }}>
              {liveProposals.map((p) => (
                <View
                  key={p.id}
                  style={[
                    styles.proposalBox,
                    { borderColor: c.cardBorder, backgroundColor: c.bgElevated },
                  ]}
                >
                  <Text style={{ color: c.text, fontFamily: "Inter_700Bold", fontSize: 13 }}>
                    {p.summary}
                  </Text>
                  <Text
                    style={{
                      color: c.textSecondary,
                      fontFamily: "Inter_400Regular",
                      fontSize: 12,
                      marginTop: 4,
                      lineHeight: 17,
                    }}
                  >
                    {p.rationale}
                  </Text>
                  {p.changes.settingsPatch && Object.keys(p.changes.settingsPatch).length > 0 ? (
                    <Text
                      style={{
                        color: c.violet,
                        fontFamily: "Inter_500Medium",
                        fontSize: 11,
                        marginTop: 6,
                      }}
                    >
                      Will toggle:{" "}
                      {Object.entries(p.changes.settingsPatch)
                        .map(([k, v]) => `${k}=${String(v)}`)
                        .join(", ")}
                    </Text>
                  ) : null}
                  {confirmingId === p.id ? (
                    <View
                      style={{
                        marginTop: 10,
                        padding: 10,
                        borderRadius: 10,
                        borderWidth: 1,
                        borderColor: c.amber,
                        backgroundColor: c.cardSubtle,
                      }}
                    >
                      <Text
                        style={{
                          color: c.text,
                          fontFamily: "Inter_600SemiBold",
                          fontSize: 12,
                        }}
                      >
                        Confirm: apply &quot;{p.summary}&quot;?
                      </Text>
                      <Text
                        style={{
                          color: c.textMuted,
                          fontFamily: "Inter_400Regular",
                          fontSize: 11,
                          marginTop: 2,
                        }}
                      >
                        This will mutate your live settings. You can roll back from the snapshot below.
                      </Text>
                    </View>
                  ) : null}
                  <View style={{ flexDirection: "row", gap: 8, marginTop: 10 }}>
                    <View style={{ flex: 1 }}>
                      <PrimaryButton
                        label={
                          applyingId === p.id
                            ? "Applying…"
                            : confirmingId === p.id
                              ? "Tap again to confirm"
                              : "Apply"
                        }
                        icon={confirmingId === p.id ? "warning" : "checkmark"}
                        variant="success"
                        loading={applyingId === p.id}
                        onPress={() => onApply(p)}
                        fullWidth
                      />
                    </View>
                    <View style={{ flex: 1 }}>
                      <PrimaryButton
                        label={confirmingId === p.id ? "Cancel" : "Dismiss"}
                        icon="close-outline"
                        variant="outline"
                        onPress={() => {
                          if (confirmingId === p.id) {
                            setConfirmingId(null);
                          } else {
                            dismissProposal(p.id);
                          }
                        }}
                        fullWidth
                      />
                    </View>
                  </View>
                </View>
              ))}
            </View>
          ) : null}

          {recentSnapshot ? (
            <View style={{ marginTop: 12 }}>
              <PrimaryButton
                label="Roll Back Last Upgrade"
                icon="arrow-undo-outline"
                variant="outline"
                onPress={onRollback}
                fullWidth
              />
              <Text
                style={{
                  textAlign: "center",
                  color: c.textDim,
                  fontFamily: "Inter_400Regular",
                  fontSize: 11,
                  marginTop: 6,
                }}
              >
                Latest snapshot: {recentSnapshot.label}
              </Text>
            </View>
          ) : null}
        </Card>

        {/* Agent Pipeline preview */}
        <Card>
          <View style={[styles.sectionRow, { justifyContent: "space-between" }]}>
            <Text style={[styles.sectionTitle, { color: c.text }]}>
              Agent Pipeline
            </Text>
            <Pressable
              onPress={() => router.push("/agents")}
              hitSlop={8}
              style={{ flexDirection: "row", alignItems: "center", gap: 4 }}
            >
              <Text style={{ color: c.violet, fontSize: 12, fontFamily: "Inter_500Medium" }}>
                View agents
              </Text>
              <Ionicons name="chevron-forward" size={14} color={c.violet} />
            </Pressable>
          </View>
          <PipelinePreview compact />
          <Text style={[styles.sectionDesc, { color: c.textMuted, marginTop: 8 }]}>
            FREE Pollinations AI · Auto-retry 4× · Continue/Retry/Restart on error
          </Text>
        </Card>

        {/* Quick Build CTA */}
        <Card>
          <Text style={[styles.cardLabel, { color: c.textMuted }]}>START A BUILD</Text>
          <PrimaryButton
            label="New Build"
            icon="sparkles"
            onPress={() => router.push("/new-build")}
            fullWidth
          />
        </Card>

        {/* Preset Builds */}
        <View>
          <Text style={[styles.cardLabel, { color: c.textMuted, marginBottom: 8 }]}>
            PRESET BUILDS
          </Text>
          <View style={{ gap: 10 }}>
            {PRESET_BUILDS.map((p) => (
              <Pressable key={p.id} onPress={() => usePreset(p)}>
                <Card style={styles.presetRow}>
                  <View
                    style={[
                      styles.presetIcon,
                      { backgroundColor: c.cardSubtle, borderColor: c.cardBorder },
                    ]}
                  >
                    {/* eslint-disable-next-line @typescript-eslint/no-explicit-any */}
                    <MaterialCommunityIcons name={p.icon as any} size={20} color={p.color} />
                  </View>
                  <View style={{ flex: 1 }}>
                    <Text style={[styles.presetTitle, { color: c.text }]}>
                      {p.title}
                    </Text>
                    <Text style={[styles.presetSub, { color: c.amber }]}>
                      {p.subtitle}
                    </Text>
                  </View>
                  <Ionicons name="chevron-forward" size={18} color={c.textDim} />
                </Card>
              </Pressable>
            ))}
          </View>
        </View>

        {/* Quick links */}
        <View style={styles.quickRow}>
          <QuickLink
            label="Memory"
            icon="ellipse-outline"
            count={memories.length}
            onPress={() => router.push("/memory")}
          />
          <QuickLink
            label="Projects"
            icon="folder-outline"
            count={projects.length}
            onPress={() => router.push("/projects")}
          />
          <QuickLink
            label="Training"
            icon="school-outline"
            count={16}
            onPress={() => router.push("/training")}
          />
        </View>
      </ScrollView>

      <SideMenu visible={menuOpen} onClose={() => setMenuOpen(false)} />
    </View>
  );
}

function QuickLink({
  label,
  icon,
  count,
  onPress,
}: {
  label: string;
  icon: keyof typeof Ionicons.glyphMap;
  count: number;
  onPress: () => void;
}) {
  const c = useColors();
  return (
    <Pressable onPress={onPress} style={{ flex: 1 }}>
      <Card style={{ alignItems: "center", padding: 14, gap: 4 }}>
        <Ionicons name={icon} size={20} color={c.violet} />
        <Text style={{ color: c.text, fontFamily: "Inter_700Bold", fontSize: 18 }}>
          {count}
        </Text>
        <Text style={{ color: c.textMuted, fontFamily: "Inter_500Medium", fontSize: 11 }}>
          {label}
        </Text>
      </Card>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  heroRow: {
    flexDirection: "row",
    alignItems: "center",
    gap: 12,
    paddingVertical: 4,
  },
  heroIcon: {
    width: 44,
    height: 44,
    borderRadius: 12,
    borderWidth: 1,
    alignItems: "center",
    justifyContent: "center",
  },
  heroTitle: {
    fontFamily: "Inter_700Bold",
    fontSize: 22,
  },
  heroSub: {
    fontFamily: "Inter_400Regular",
    fontSize: 12,
    marginTop: 2,
  },
  statRow: {
    flexDirection: "row",
    gap: 10,
  },
  sectionRow: {
    flexDirection: "row",
    alignItems: "center",
    gap: 8,
    marginBottom: 6,
  },
  sectionTitle: {
    fontFamily: "Inter_700Bold",
    fontSize: 15,
  },
  sectionDesc: {
    fontFamily: "Inter_400Regular",
    fontSize: 12,
    lineHeight: 18,
