import { Ionicons } from "@expo/vector-icons";
import React, { useMemo, useState } from "react";
import {
  Alert,
  Modal,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  View,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { Card } from "@/components/Card";
import { PrimaryButton } from "@/components/PrimaryButton";
import { ScreenHeader } from "@/components/ScreenHeader";
import { SideMenu } from "@/components/SideMenu";
import { useStudio } from "@/contexts/StudioContext";
import { useColors } from "@/hooks/useColors";
import type { KnowledgeEntry } from "@/lib/types";

const FILTERS: { id: "all" | KnowledgeEntry["type"]; label: string }[] = [
  { id: "all", label: "All" },
  { id: "snippet", label: "Snippets" },
  { id: "doc", label: "Docs" },
  { id: "fix", label: "Fixes" },
];

const PLATFORMS = ["All Platforms", "Android", "Web", "Flutter"];

export default function LibraryScreen() {
  const c = useColors();
  const insets = useSafeAreaInsets();
  const { knowledge, addKnowledge, removeKnowledge } = useStudio();
  const [menuOpen, setMenuOpen] = useState(false);
  const [filter, setFilter] = useState<"all" | KnowledgeEntry["type"]>("all");
  const [platform, setPlatform] = useState<string>("All Platforms");
  const [search, setSearch] = useState("");
  const [showAdd, setShowAdd] = useState(false);

  const counts = useMemo(() => {
    const m: Record<string, number> = { all: knowledge.length, snippet: 0, doc: 0, fix: 0 };
    knowledge.forEach((k) => {
      m[k.type] = (m[k.type] ?? 0) + 1;
    });
    return m;
  }, [knowledge]);

  const autoCount = useMemo(
    () => knowledge.filter((k) => k.autoInclude).length,
    [knowledge],
  );

  const filtered = useMemo(() => {
    return knowledge.filter((k) => {
      if (filter !== "all" && k.type !== filter) return false;
      if (platform !== "All Platforms") {
        if (!k.tags.some((t) => t.toLowerCase() === platform.toLowerCase())) return false;
      }
      if (search.trim()) {
        const q = search.toLowerCase();
        if (!k.title.toLowerCase().includes(q) && !k.body.toLowerCase().includes(q))
          return false;
      }
      return true;
    });
  }, [filter, knowledge, platform, search]);

  return (
    <View style={{ flex: 1, backgroundColor: c.bg }}>
      <ScreenHeader
        title="Knowledge Library"
        showMenu
        onMenuPress={() => setMenuOpen(true)}
        right={
          <Pressable onPress={() => setShowAdd(true)} hitSlop={10}>
            <View
              style={[
                styles.addBtn,
                { backgroundColor: c.cardSubtle, borderColor: c.cardBorder },
              ]}
            >
              <Ionicons name="add" size={16} color={c.text} />
              <Text style={{ color: c.text, fontFamily: "Inter_600SemiBold", fontSize: 12 }}>
                Add
              </Text>
            </View>
          </Pressable>
        }
      />
      <ScrollView
        contentContainerStyle={{
          padding: 16,
          paddingBottom: insets.bottom + 120,
          gap: 16,
        }}
      >
        <Text style={[styles.subtitle, { color: c.textMuted }]}>
          Code patterns, fixes & docs your agents reference during builds.
        </Text>

        <View style={{ flexDirection: "row", gap: 10 }}>
          <SummaryTile
            count={counts.all}
            label="Entries"
            color={c.green}
            background={c.greenSoft}
            border={c.greenBorder}
            icon="book-outline"
          />
          <SummaryTile
            count={autoCount}
            label="Auto-included"
            color={c.amber}
            background={c.amberSoft}
            border={c.amberBorder}
            icon="flash"
          />
          <SummaryTile
            count={counts.snippet}
            label="Snippets"
            color={c.violet}
            background={c.primarySoft}
            border={c.primarySoftBorder}
            icon="code-slash-outline"
          />
        </View>

        <View
          style={[
            styles.searchBox,
            { backgroundColor: c.bgElevated, borderColor: c.cardBorder },
          ]}
        >
          <Ionicons name="search" size={16} color={c.textMuted} />
          <TextInput
            value={search}
            onChangeText={setSearch}
            placeholder="Search knowledge base..."
            placeholderTextColor={c.textDim}
            style={{
              flex: 1,
              color: c.text,
              fontFamily: "Inter_400Regular",
              fontSize: 14,
            }}
          />
        </View>

        <ScrollView horizontal showsHorizontalScrollIndicator={false}>
          <View style={{ flexDirection: "row", gap: 8 }}>
            {FILTERS.map((f) => {
              const active = filter === f.id;
              return (
                <Pressable key={f.id} onPress={() => setFilter(f.id)}>
                  <View
                    style={[
                      styles.chip,
                      {
                        backgroundColor: active ? c.primarySoft : c.cardSubtle,
                        borderColor: active ? c.primarySoftBorder : c.cardBorder,
                      },
                    ]}
                  >
                    <Text
                      style={{
                        color: active ? c.violet : c.textSecondary,
                        fontFamily: "Inter_600SemiBold",
                        fontSize: 12,
                      }}
                    >
                      {f.label} ({counts[f.id]})
                    </Text>
                  </View>
                </Pressable>
              );
            })}
          </View>
        </ScrollView>

        <ScrollView horizontal showsHorizontalScrollIndicator={false}>
          <View style={{ flexDirection: "row", gap: 8 }}>
            {PLATFORMS.map((p) => {
              const active = platform === p;
              return (
                <Pressable key={p} onPress={() => setPlatform(p)}>
                  <View
                    style={[
                      styles.chip,
                      {
                        backgroundColor: active ? c.cardSubtle : "transparent",
                        borderColor: active ? c.cardBorder : c.cardBorderSubtle,
                      },
                    ]}
                  >
                    <Text
                      style={{
                        color: active ? c.text : c.textMuted,
                        fontFamily: "Inter_500Medium",
                        fontSize: 12,
                      }}
                    >
                      {p}
                    </Text>
                  </View>
                </Pressable>
              );
            })}
          </View>
        </ScrollView>

        <View style={{ gap: 10 }}>
          {filtered.map((k) => (
            <Card key={k.id}>
              <View style={styles.knHeader}>
                <View
                  style={[
                    styles.typeBadge,
                    {
                      borderColor:
                        k.type === "doc" ? c.blue : k.type === "fix" ? c.amber : c.violet,
                    },
                  ]}
                >
                  <Text
                    style={{
                      color:
                        k.type === "doc" ? c.blue : k.type === "fix" ? c.amber : c.violet,
                      fontFamily: "Inter_700Bold",
                      fontSize: 10,
                      letterSpacing: 0.5,
                    }}
                  >
                    {k.type.toUpperCase()}
                  </Text>
                </View>
                <Text style={[styles.title, { color: c.text }]} numberOfLines={2}>
                  {k.title}
                </Text>
                <View style={{ flexDirection: "row", gap: 12 }}>
                  <Pressable hitSlop={6}>
                    <Ionicons name="copy-outline" size={16} color={c.textDim} />
                  </Pressable>
                  <Pressable
                    hitSlop={6}
                    onPress={() =>
                      Alert.alert("Delete entry?", k.title, [
                        { text: "Cancel" },
                        {
                          text: "Delete",
                          style: "destructive",
                          onPress: () => removeKnowledge(k.id),
                        },
                      ])
                    }
                  >
                    <Ionicons name="trash-outline" size={16} color={c.textDim} />
                  </Pressable>
                </View>
              </View>
              {k.body ? (
                <Text style={[styles.body, { color: c.textMuted }]} numberOfLines={2}>
                  {k.body}
                </Text>
              ) : null}
              <View style={styles.tagRow}>
                {k.tags.map((t) => (
                  <View
                    key={t}
                    style={[
                      styles.tag,
                      { backgroundColor: c.cardSubtle, borderColor: c.cardBorder },
                    ]}
                  >
                    <Text style={{ color: c.textSecondary, fontSize: 11 }}>{t}</Text>
                  </View>
                ))}
              </View>
            </Card>
          ))}
        </View>
      </ScrollView>

      <AddKnowledgeModal
        visible={showAdd}
        onClose={() => setShowAdd(false)}
        onSave={(entry) => addKnowledge(entry)}
      />

      <SideMenu visible={menuOpen} onClose={() => setMenuOpen(false)} />
    </View>
  );
}

function SummaryTile({
  count,
  label,
  color,
  background,
  border,
  icon,
}: {
  count: number;
  label: string;
  color: string;
  background: string;
  border: string;
  icon: keyof typeof Ionicons.glyphMap;
}) {
  const c = useColors();
  return (
    <View
      style={[
        styles.summary,
        { backgroundColor: background, borderColor: border, borderRadius: c.radius },
      ]}
    >
      <Ionicons name={icon} size={16} color={color} />
      <Text style={[styles.summaryNum, { color: c.text }]}>{count}</Text>
      <Text style={[styles.summaryLabel, { color }]}>{label}</Text>
    </View>
  );
}

function AddKnowledgeModal({
  visible,
  onClose,
  onSave,
}: {
  visible: boolean;
  onClose: () => void;
  onSave: (k: Omit<KnowledgeEntry, "id" | "createdAt">) => void;
}) {
  const c = useColors();
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const [tags, setTags] = useState("");
  const [type, setType] = useState<KnowledgeEntry["type"]>("snippet");
  const [autoInclude, setAutoInclude] = useState(false);

  const submit = () => {
    if (!title.trim()) return;
    onSave({
      title: title.trim(),
      body: body.trim(),
      tags: tags.split(",").map((t) => t.trim()).filter(Boolean),
      type,
      autoInclude,
    });
    setTitle("");
    setBody("");
    setTags("");
    setType("snippet");
    setAutoInclude(false);
    onClose();
  };

  return (
    <Modal visible={visible} animationType="slide" transparent onRequestClose={onClose}>
      <Pressable style={styles.modalBackdrop} onPress={onClose}>
        <Pressable
          onPress={(e) => e.stopPropagation()}
          style={[
            styles.modalSheet,
            { backgroundColor: c.bg, borderTopColor: c.cardBorder },
          ]}
        >
          <View style={styles.modalHeader}>
            <Text style={{ color: c.text, fontFamily: "Inter_700Bold", fontSize: 18 }}>
              New Knowledge Entry
            </Text>
            <Pressable onPress={onClose} hitSlop={10}>
              <Ionicons name="close" size={22} color={c.text} />
            </Pressable>
          </View>
          <ScrollView contentContainerStyle={{ gap: 12, paddingBottom: 32 }}>
            <View style={{ flexDirection: "row", gap: 8 }}>
              {(["snippet", "doc", "fix"] as const).map((t) => {
                const active = type === t;
                return (
                  <Pressable key={t} onPress={() => setType(t)} style={{ flex: 1 }}>
                    <View
                      style={[
                        styles.chip,
                        {
                          alignItems: "center",
                          backgroundColor: active ? c.primarySoft : c.cardSubtle,
                          borderColor: active ? c.primarySoftBorder : c.cardBorder,
                        },
                      ]}
                    >
                      <Text
                        style={{
                          color: active ? c.violet : c.textSecondary,
                          fontFamily: "Inter_600SemiBold",
                          fontSize: 12,
                          textTransform: "uppercase",
                        }}
                      >
                        {t}
                      </Text>
                    </View>
                  </Pressable>
                );
              })}
            </View>
            <TextInput
              value={title}
              onChangeText={setTitle}
              placeholder="Title"
              placeholderTextColor={c.textDim}
              style={[styles.input, { color: c.text, borderColor: c.cardBorder, backgroundColor: c.bgElevated }]}
            />
            <TextInput
              value={body}
              onChangeText={setBody}
              placeholder="Body / code"
              placeholderTextColor={c.textDim}
              multiline
              style={[
                styles.input,
                {
                  color: c.text,
                  borderColor: c.cardBorder,
                  backgroundColor: c.bgElevated,
                  minHeight: 100,
                  textAlignVertical: "top",
                },
              ]}
            />
            <TextInput
              value={tags}
              onChangeText={setTags}
              placeholder="Tags (comma separated)"
              placeholderTextColor={c.textDim}
              style={[styles.input, { color: c.text, borderColor: c.cardBorder, backgroundColor: c.bgElevated }]}
            />
            <Pressable
              onPress={() => setAutoInclude((v) => !v)}
              style={{ flexDirection: "row", alignItems: "center", gap: 10, paddingVertical: 8 }}
            >
              <Ionicons
                name={autoInclude ? "checkbox" : "square-outline"}
                size={20}
                color={autoInclude ? c.violet : c.textMuted}
              />
              <Text style={{ color: c.text, fontFamily: "Inter_500Medium", fontSize: 13 }}>
                Auto-include on every build
              </Text>
            </Pressable>
            <PrimaryButton label="Save Entry" icon="save-outline" onPress={submit} fullWidth />
          </ScrollView>
        </Pressable>
      </Pressable>
    </Modal>
  );
}

