import { Ionicons } from "@expo/vector-icons";
import React, { useMemo, useState } from "react";
import {
  Alert,
  Modal,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  View,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { Card } from "@/components/Card";
import { PrimaryButton } from "@/components/PrimaryButton";
import { ScreenHeader } from "@/components/ScreenHeader";
import { SideMenu } from "@/components/SideMenu";
import { useStudio } from "@/contexts/StudioContext";
import { useColors } from "@/hooks/useColors";
import type { MemoryEntry } from "@/lib/types";

const FILTERS: { id: "all" | MemoryEntry["type"]; label: string }[] = [
  { id: "all", label: "All" },
  { id: "issue", label: "Issue" },
  { id: "solution", label: "Solution" },
  { id: "snippet", label: "Snippet" },
  { id: "doc", label: "Doc" },
];

export default function MemoryScreen() {
  const c = useColors();
  const insets = useSafeAreaInsets();
  const { memories, addMemory, removeMemory } = useStudio();
  const [menuOpen, setMenuOpen] = useState(false);
  const [filter, setFilter] = useState<"all" | MemoryEntry["type"]>("all");
  const [showAdd, setShowAdd] = useState(false);

  const counts = useMemo(() => {
    const m: Record<string, number> = {
      all: memories.length,
      issue: 0,
      solution: 0,
      snippet: 0,
      doc: 0,
    };
    memories.forEach((x) => {
      m[x.type] = (m[x.type] ?? 0) + 1;
    });
    return m;
  }, [memories]);

  const filtered = useMemo(
    () => (filter === "all" ? memories : memories.filter((m) => m.type === filter)),
    [filter, memories],
  );

  const autoCount = useMemo(
    () => memories.filter((m) => m.autoInclude).length,
    [memories],
  );

  return (
    <View style={{ flex: 1, backgroundColor: c.bg }}>
      <ScreenHeader
        title="Memory"
        showMenu
        onMenuPress={() => setMenuOpen(true)}
        right={
          <Pressable onPress={() => setShowAdd(true)} hitSlop={10}>
            <View
              style={[
                styles.addBtn,
                { backgroundColor: c.cardSubtle, borderColor: c.cardBorder },
              ]}
            >
              <Ionicons name="add" size={16} color={c.text} />
              <Text style={{ color: c.text, fontFamily: "Inter_600SemiBold", fontSize: 12 }}>
                Add
              </Text>
            </View>
          </Pressable>
        }
      />
      <ScrollView
        contentContainerStyle={{
          padding: 16,
          paddingBottom: insets.bottom + 120,
          gap: 16,
        }}
      >
        <Text style={[styles.subtitle, { color: c.textMuted }]}>
          Reference info your agents pull from. Saved on device, works offline.
        </Text>

        <View style={{ flexDirection: "row", gap: 10 }}>
          <View
            style={[
              styles.statCard,
              { backgroundColor: c.greenSoft, borderColor: c.greenBorder },
            ]}
          >
            <Ionicons name="cloud-offline-outline" size={16} color={c.green} />
            <Text style={[styles.statTitle, { color: c.green }]}>Offline-ready</Text>
            <Text style={[styles.statSub, { color: c.textSecondary }]}>
              All memories live on this device.
            </Text>
          </View>
          <View
            style={[
              styles.statCard,
              { backgroundColor: c.amberSoft, borderColor: c.amberBorder },
            ]}
          >
            <Ionicons name="flash" size={16} color={c.amber} />
            <Text style={[styles.statTitle, { color: c.amber }]}>
              {autoCount} auto-included
            </Text>
            <Text style={[styles.statSub, { color: c.textSecondary }]}>
              Sent to agents on every build.
            </Text>
          </View>
        </View>

        <ScrollView horizontal showsHorizontalScrollIndicator={false}>
          <View style={{ flexDirection: "row", gap: 8 }}>
            {FILTERS.map((f) => {
              const active = filter === f.id;
              return (
                <Pressable key={f.id} onPress={() => setFilter(f.id)}>
                  <View
                    style={[
                      styles.filterChip,
                      {
                        backgroundColor: active ? c.primarySoft : c.cardSubtle,
                        borderColor: active ? c.primarySoftBorder : c.cardBorder,
                      },
                    ]}
                  >
                    <Text
                      style={{
                        color: active ? c.violet : c.textSecondary,
                        fontFamily: "Inter_600SemiBold",
                        fontSize: 12,
                      }}
                    >
                      {f.label} ({counts[f.id]})
                    </Text>
                  </View>
                </Pressable>
              );
            })}
          </View>
        </ScrollView>

        <View style={{ gap: 10 }}>
          {filtered.map((m) => (
            <Card key={m.id}>
              <View style={styles.memHeader}>
                <View
                  style={[
                    styles.memTypeBadge,
                    {
                      borderColor:
                        m.type === "doc"
                          ? c.blue
                          : m.type === "solution"
                            ? c.green
                            : m.type === "snippet"
                              ? c.violet
                              : c.amber,
                    },
                  ]}
                >
                  <Text
                    style={{
                      color:
                        m.type === "doc"
                          ? c.blue
                          : m.type === "solution"
                            ? c.green
                            : m.type === "snippet"
                              ? c.violet
                              : c.amber,
                      fontFamily: "Inter_700Bold",
                      fontSize: 10,
                      letterSpacing: 0.5,
                    }}
                  >
                    {m.type.toUpperCase()}
                  </Text>
                </View>
                <Text style={[styles.memTitle, { color: c.text }]} numberOfLines={2}>
                  {m.title}
                </Text>
                <Pressable
                  onPress={() =>
                    Alert.alert("Delete memory?", m.title, [
                      { text: "Cancel" },
                      {
                        text: "Delete",
                        style: "destructive",
                        onPress: () => removeMemory(m.id),
                      },
                    ])
                  }
                  hitSlop={8}
                >
                  <Ionicons name="trash-outline" size={16} color={c.textDim} />
                </Pressable>
              </View>
              {m.body ? (
                <Text style={[styles.memBody, { color: c.textMuted }]} numberOfLines={2}>
                  {m.body}
                </Text>
              ) : null}
              <View style={styles.tagRow}>
                {m.tags.map((t) => (
                  <View
                    key={t}
                    style={[
                      styles.tag,
                      { backgroundColor: c.cardSubtle, borderColor: c.cardBorder },
                    ]}
                  >
                    <Text style={{ color: c.textSecondary, fontSize: 11 }}>{t}</Text>
                  </View>
                ))}
              </View>
            </Card>
          ))}
        </View>
      </ScrollView>

      <AddMemoryModal
        visible={showAdd}
        onClose={() => setShowAdd(false)}
        onSave={(entry) => addMemory(entry)}
      />

      <SideMenu visible={menuOpen} onClose={() => setMenuOpen(false)} />
    </View>
  );
}

function AddMemoryModal({
  visible,
  onClose,
  onSave,
}: {
  visible: boolean;
  onClose: () => void;
  onSave: (m: Omit<MemoryEntry, "id" | "createdAt">) => void;
}) {
  const c = useColors();
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const [tags, setTags] = useState("");
  const [type, setType] = useState<MemoryEntry["type"]>("doc");
  const [autoInclude, setAutoInclude] = useState(true);

  const submit = () => {
    if (!title.trim()) return;
    onSave({
      title: title.trim(),
      body: body.trim(),
      tags: tags
        .split(",")
        .map((t) => t.trim())
        .filter(Boolean),
      type,
      autoInclude,
    });
    setTitle("");
    setBody("");
    setTags("");
    setType("doc");
    setAutoInclude(true);
    onClose();
  };

  return (
    <Modal visible={visible} animationType="slide" transparent onRequestClose={onClose}>
      <Pressable style={styles.modalBackdrop} onPress={onClose}>
        <Pressable
          onPress={(e) => e.stopPropagation()}
          style={[
            styles.modalSheet,
            { backgroundColor: c.bg, borderTopColor: c.cardBorder },
          ]}
        >
          <View style={styles.modalHeader}>
            <Text style={{ color: c.text, fontFamily: "Inter_700Bold", fontSize: 18 }}>
              New Memory
            </Text>
            <Pressable onPress={onClose} hitSlop={10}>
              <Ionicons name="close" size={22} color={c.text} />
            </Pressable>
          </View>

          <ScrollView contentContainerStyle={{ gap: 12, paddingBottom: 32 }}>
            <View style={{ flexDirection: "row", gap: 8 }}>
              {(["doc", "issue", "solution", "snippet"] as const).map((t) => {
                const active = type === t;
                return (
                  <Pressable key={t} onPress={() => setType(t)} style={{ flex: 1 }}>
                    <View
                      style={[
                        styles.typeChip,
                        {
                          backgroundColor: active ? c.primarySoft : c.cardSubtle,
                          borderColor: active ? c.primarySoftBorder : c.cardBorder,
                        },
                      ]}
                    >
                      <Text
                        style={{
                          color: active ? c.violet : c.textSecondary,
                          fontFamily: "Inter_600SemiBold",
                          fontSize: 12,
                          textTransform: "uppercase",
                        }}
                      >
                        {t}
                      </Text>
                    </View>
                  </Pressable>
                );
              })}
            </View>

            <Field label="Title">
              <TextInput
                value={title}
                onChangeText={setTitle}
                placeholder="e.g., Kotlin null safety patterns"
                placeholderTextColor={c.textDim}
                style={[styles.fieldInput, { color: c.text, borderColor: c.cardBorder, backgroundColor: c.bgElevated }]}
              />
            </Field>
            <Field label="Body">
              <TextInput
                value={body}
                onChangeText={setBody}
                placeholder="Notes, code, examples…"
                placeholderTextColor={c.textDim}
                multiline
                style={[
                  styles.fieldInput,
                  {
                    color: c.text,
                    borderColor: c.cardBorder,
                    backgroundColor: c.bgElevated,
                    minHeight: 100,
                    textAlignVertical: "top",
                  },
                ]}
              />
            </Field>
            <Field label="Tags (comma separated)">
              <TextInput
                value={tags}
                onChangeText={setTags}
                placeholder="kotlin, android, learned"
                placeholderTextColor={c.textDim}
                style={[styles.fieldInput, { color: c.text, borderColor: c.cardBorder, backgroundColor: c.bgElevated }]}
              />
            </Field>

            <Pressable
              onPress={() => setAutoInclude((v) => !v)}
              style={{
                flexDirection: "row",
                alignItems: "center",
                gap: 10,
                paddingVertical: 8,
              }}
            >
              <Ionicons
                name={autoInclude ? "checkbox" : "square-outline"}
                size={20}
                color={autoInclude ? c.violet : c.textMuted}
              />
              <Text style={{ color: c.text, fontFamily: "Inter_500Medium", fontSize: 13 }}>
                Auto-include on every build
              </Text>
            </Pressable>

            <PrimaryButton label="Save Memory" icon="save-outline" onPress={submit} fullWidth />
          </ScrollView>
        </Pressable>
      </Pressable>
    </Modal>
  );
}

function Field({ label, children }: { label: string; children: React.ReactNode }) {
  const c = useColors();
  return (
    <View style={{ gap: 6 }}>
      <Text
        style={{
          color: c.textMuted,
          fontFamily: "Inter_600SemiBold",
          fontSize: 11,
          letterSpacing: 0.5,
          textTransform: "uppercase",
        }}
      >
        {label}
      </Text>
      {children}
    </View>
  );
}

