import type { HealthCheck, HealthName } from "@/lib/types";

type Tab = "ai" | "prefs" | "infra";

export default function SettingsScreen() {
  const c = useColors();
  const insets = useSafeAreaInsets();
  const {
    settings,
    updateSettings,
    projects,
    memories,
    exportProject,
    exportSourceCode,
    pushToGithub,
    snapshots,
    rollbackUpgrade,
  } = useStudio();
  const [exporting, setExporting] = useState<"source" | "all" | null>(null);
  const [pushingId, setPushingId] = useState<string | null>(null);
  const [pushProgress, setPushProgress] = useState<string>("");
  const [menuOpen, setMenuOpen] = useState(false);
  const [tab, setTab] = useState<Tab>("ai");
  const [groqKey, setGroqKey] = useState(settings.groqKey);
  const [customKey, setCustomKey] = useState(settings.customKey);
  const [githubToken, setGithubToken] = useState(settings.githubToken);
  const [githubRepo, setGithubRepo] = useState(settings.githubRepo);
  const [proxyUrl, setProxyUrl] = useState(settings.proxyUrl);
  const [authHeader, setAuthHeader] = useState(settings.authorizationHeader);
  const sourceSummary = useMemo(() => getSourceBundleSummary(), []);
  const pushCandidates = projects.filter((p) => p.status === "ready" || p.status === "failed");
  const [healthChecks, setHealthChecks] = useState<HealthCheck[]>(
    initialHealth(),
  );
  const [healthRunning, setHealthRunning] = useState(false);
  const [testingGroq, setTestingGroq] = useState(false);

  const runHealthChecks = async () => {
    setHealthRunning(true);
    const list = initialHealth().map((h) => ({ ...h, state: "checking" as const }));
    setHealthChecks(list);

    const order: HealthName[] = ["pollinations", "groq", "custom", "proxy", "auth", "cache"];
    for (const name of order) {
      let ok = false;
      let detail = "";
      switch (name) {
        case "pollinations":
          ok = await pingPollinations();
          detail = ok ? "Reachable · openai-fast available" : "Unreachable";
          break;
        case "groq":
          ok = settings.groqKey.trim().length > 0;
          detail = ok ? "Key present (validate via Test Connection)" : "Not configured";
          break;
        case "custom":
          ok = settings.customKey.trim().length > 0;
          detail = ok ? "Custom key present" : "Not configured";
          break;
        case "proxy":
          ok = settings.proxyUrl.trim().length > 0;
          detail = ok ? "Proxy URL present" : "Not configured";
          break;
        case "auth":
          ok = settings.authorizationHeader.trim().length > 0;
          detail = ok ? "Header present" : "Not configured";
          break;
        case "cache":
          ok = true;
          detail = "AsyncStorage writable";
          break;
      }
      setHealthChecks((prev) =>
        prev.map((h) => (h.name === name ? { ...h, state: ok ? "ok" : "fail", detail } : h)),
      );
      await new Promise((r) => setTimeout(r, 200));
    }

    setHealthRunning(false);
  };

  const testGroq = async () => {
    if (!groqKey.trim()) {
      Alert.alert("Add a Groq key first.");
      return;
    }
    setTestingGroq(true);
    try {
      // Light test via Pollinations as proxy — Groq direct call would require CORS; we just probe Pollinations to confirm pipeline is alive.
      const out = await pollinate(
        [
          { role: "system", content: "Reply with just OK." },
          { role: "user", content: "ping" },
        ],
        { temperature: 0 },
      );
      Alert.alert("Connection OK", `Pipeline reachable. Response: ${out.slice(0, 60)}…`);
    } catch (e) {
      const msg = e instanceof Error ? e.message : "failed";
      Alert.alert("Connection failed", msg);
    } finally {
      setTestingGroq(false);
    }
  };

  const wipeStorage = () => {
    Alert.alert(
      "Reset all device data?",
      "This deletes projects, memories, knowledge and settings on this device.",
      [
        { text: "Cancel" },
        {
          text: "Reset",
          style: "destructive",
          onPress: async () => {
            await clearAll();
            Alert.alert("Reset complete", "Restart the app to see seed data again.");
          },
        },
      ],
    );
  };

  const memoryCount = memories.length;

  return (
    <View style={{ flex: 1, backgroundColor: c.bg }}>
      <ScreenHeader
        title="Settings"
        subtitle="Configure your agents' intelligence engine"
        showMenu
        onMenuPress={() => setMenuOpen(true)}
      />

      <ScrollView
        contentContainerStyle={{
          padding: 16,
          paddingBottom: insets.bottom + 120,
          gap: 16,
        }}
      >
        {/* Tab bar */}
        <View
          style={[
            styles.tabBar,
            { borderBottomColor: c.cardBorderSubtle },
          ]}
        >
          <TabButton label="AI Settings" icon="flash-outline" active={tab === "ai"} onPress={() => setTab("ai")} />
          <TabButton label="Preferences" icon="settings-outline" active={tab === "prefs"} onPress={() => setTab("prefs")} />
          <TabButton label="Infrastructure" icon="pulse-outline" active={tab === "infra"} onPress={() => setTab("infra")} />
        </View>

        {tab === "ai" ? (
          <>
            <Card style={{ backgroundColor: c.primarySoft, borderColor: c.primarySoftBorder }}>
              <View style={{ flexDirection: "row", gap: 10 }}>
                <Ionicons name="flash" size={18} color={c.violet} style={{ marginTop: 2 }} />
                <View style={{ flex: 1 }}>
                  <Text style={[styles.calloutTitle, { color: c.violet }]}>
                    ⚡ Pollinations AI — Primary (Always Free)
                  </Text>
                  <Text style={[styles.calloutBody, { color: c.textSecondary }]}>
                    No API key needed. No limits. No credits. Powered by openai-fast model.
                  </Text>
                </View>
              </View>
            </Card>

            <Card>
              <Text style={[styles.sectionLabel, { color: c.textMuted }]}>AI PRIORITY ORDER</Text>
              <PriorityRow num={1} title="Pollinations AI" sub="openai-fast" pill={{ tone: "violet", label: "FREE · No Limits · No Key" }} active />
              <PriorityRow num={2} title="Groq (if key set)" sub="llama3-70b-8192" pill={{ tone: "green", label: "FREE · Ultra Fast" }} />
              <PriorityRow num={3} title="Custom API Key" sub="Pollinations (your key)" pill={{ tone: "amber", label: "Your Key" }} />
              <PriorityRow num={4} title="Platform AI" sub="gemini-2.0-flash" pill={{ tone: "muted", label: "Fallback" }} isLast />
            </Card>

            <Card>
              <Text style={[styles.fieldTitle, { color: c.text }]}>
                Groq API Key (Optional — Free)
              </Text>
              <Text style={[styles.fieldHint, { color: c.textMuted }]}>
                Add a free Groq key for faster, smarter agents. Get one at console.groq.com
              </Text>
              <KeyInput value={groqKey} onChange={setGroqKey} placeholder="gsk_…" />
              <View style={{ flexDirection: "row", gap: 10, marginTop: 12 }}>
                <View style={{ flex: 1 }}>
                  <PrimaryButton
                    label="Save Key"
                    icon="save-outline"
                    variant="primary"
                    onPress={() => updateSettings({ groqKey })}
                    fullWidth
                  />
                </View>
                <View style={{ flex: 1 }}>
                  <PrimaryButton
                    label="Test Connection"
                    icon="pulse-outline"
                    variant="outline"
                    onPress={testGroq}
                    loading={testingGroq}
                    fullWidth
                  />
                </View>
              </View>
            </Card>

            <Card>
              <Text style={[styles.fieldTitle, { color: c.text }]}>
                Custom API Key (Optional)
              </Text>
              <Text style={[styles.fieldHint, { color: c.textMuted }]}>
                Add your own OpenAI API key as an additional fallback. Used after Pollinations and Groq.
              </Text>
              <KeyInput value={customKey} onChange={setCustomKey} placeholder="sk-…" />
              <View style={{ marginTop: 12 }}>
                <PrimaryButton
                  label="Save Custom Key"
                  icon="save-outline"
                  onPress={() => updateSettings({ customKey })}
                  fullWidth
                />
              </View>
              <Text
                style={{
                  textAlign: "center",
                  color: c.textDim,
                  fontSize: 11,
                  marginTop: 8,
                  fontFamily: "Inter_400Regular",
                }}
              >
                Stored locally on your device only
              </Text>
            </Card>

            <Card>
              <View style={{ flexDirection: "row", alignItems: "center", gap: 8 }}>
                <Ionicons name="logo-github" size={18} color={c.text} />
                <Text style={[styles.fieldTitle, { color: c.text, marginBottom: 0 }]}>
                  GitHub Token (Optional)
                </Text>
              </View>
              <Text style={[styles.fieldHint, { color: c.textMuted, marginTop: 8 }]}>
                Connect a Personal Access Token with repo scope to import and push projects.
              </Text>
              <KeyInput value={githubToken} onChange={setGithubToken} placeholder="ghp_…" />
              <Text style={[styles.fieldTitle, { color: c.text, marginTop: 14 }]}>
                Default Repo (owner/name)
              </Text>
              <Text style={[styles.fieldHint, { color: c.textMuted }]}>
                Used by every &quot;Push to GitHub&quot; button across the app.
              </Text>
              <View
                style={[
                  styles.input,
                  { borderColor: c.cardBorder, backgroundColor: c.bgElevated, marginTop: 8 },
                ]}
              >
                <TextInput
                  placeholder="myuser/my-app"
                  placeholderTextColor={c.textDim}
                  value={githubRepo}
                  onChangeText={setGithubRepo}
                  autoCapitalize="none"
                  autoCorrect={false}
                  style={{
                    color: c.text,
                    fontFamily: "Inter_400Regular",
                    fontSize: 14,
                    height: 40,
                  }}
                />
              </View>
              <View style={{ flexDirection: "row", gap: 10, marginTop: 12 }}>
                <View style={{ flex: 1 }}>
                  <PrimaryButton
                    label="Save Token & Repo"
                    icon="save-outline"
                    onPress={async () => {
                      await updateSettings({ githubToken, githubRepo });
                      Alert.alert("Saved", "GitHub token and repo saved on this device.");
                    }}
                    fullWidth
                  />
                </View>
                <View style={{ flex: 1 }}>
                  <PrimaryButton
                    label="Test Access"
                    icon="pulse-outline"
                    variant="outline"
                    onPress={async () => {
                      const repo = parseRepoSlug(githubRepo);
                      if (!repo) {
                        Alert.alert("Repo invalid", "Use the form owner/name.");
                        return;
                      }
                      if (!githubToken.trim()) {
                        Alert.alert("Token missing", "Add a GitHub token first.");
                        return;
                      }
                      const r = await verifyRepoAccess(repo, githubToken);
                      Alert.alert(r.ok ? "Repo OK" : "Access failed", r.message);
                    }}
                    fullWidth
                  />
                </View>
              </View>
            </Card>
          </>
        ) : null}

        {tab === "prefs" ? (
          <>
            <Card>
              <Text style={[styles.sectionLabel, { color: c.textMuted }]}>BUILD PREFERENCES</Text>
              <SettingRow
                icon="cloud-download-outline"
                title="Auto-download on complete"
                description="Instantly download files when all agents finish"
                value={settings.autoDownloadOnComplete}
                onChange={(v) => updateSettings({ autoDownloadOnComplete: v })}
              />
              <SettingRow
                icon="notifications-outline"
                title="Build notifications"
                description="Notify when agents complete each step"
                value={settings.buildNotifications}
                onChange={(v) => updateSettings({ buildNotifications: v })}
              />
              <SettingRow
                icon="code-slash-outline"
                title="Live Code Feed"
                description="Real-time view of code being written"
                value={settings.liveCodeFeed}
                onChange={(v) => updateSettings({ liveCodeFeed: v })}
              />
              <SettingRow
                icon="flash-outline"
                title="Self-Upgrading Agents"
                description="Agents analyze and propose improvements"
                value={settings.selfUpgradingAgents}
                onChange={(v) => updateSettings({ selfUpgradingAgents: v })}
              />
              <SettingRow
                icon="checkmark-circle-outline"
                title="Require approval for upgrades"
                description="Agents must ask before applying any change (disabled = autonomous)"
                value={settings.requireApprovalForUpgrades}
                onChange={(v) => updateSettings({ requireApprovalForUpgrades: v })}
              />
              <SettingRow
                icon="eye-outline"
                title="Preview changes before executing"
                description="Show diff — approve or reject before running"
                value={settings.previewChangesBeforeExecuting}
                onChange={(v) => updateSettings({ previewChangesBeforeExecuting: v })}
              />
              <SettingRow
                icon="refresh-outline"
                title="Auto-rollback on failure"
                description="Revert automatically if upgrade causes errors"
                value={settings.autoRollbackOnFailure}
                onChange={(v) => updateSettings({ autoRollbackOnFailure: v })}
                isLast
              />
            </Card>

            <Card>
              <View style={{ flexDirection: "row", gap: 10 }}>
                <View
                  style={[
                    styles.exportIcon,
                    { backgroundColor: c.greenSoft, borderColor: c.greenBorder },
                  ]}
                >
                  <Ionicons name="download-outline" size={18} color={c.green} />
                </View>
                <View style={{ flex: 1 }}>
                  <Text style={[styles.fieldTitle, { color: c.text, marginBottom: 2 }]}>
                    Export All Projects
                  </Text>
                  <Text style={[styles.fieldHint, { color: c.textMuted }]}>
                    {projects.length} projects · Single file download
                  </Text>
                </View>
              </View>
              <View style={{ marginTop: 12 }}>
                <PrimaryButton
                  label={exporting === "all" ? "Preparing…" : "Download All Project Files"}
                  icon="download-outline"
                  variant="success"
                  loading={exporting === "all"}
                  disabled={projects.length === 0}
                  onPress={async () => {
                    if (projects.length === 0) {
                      Alert.alert(
                        "Nothing to export",
                        "Build at least one project first.",
                      );
                      return;
                    }
                    setExporting("all");
                    let saved = 0;
                    let lastErr = "";
                    for (const p of projects) {
                      const r = await exportProject(p.id);
                      if (r.ok) saved += 1;
                      else lastErr = r.message;
                    }
                    setExporting(null);
                    Alert.alert(
                      saved > 0 ? "Bundles ready" : "Export failed",
                      saved > 0
                        ? `Saved ${saved} project bundle${saved === 1 ? "" : "s"}.`
                        : lastErr || "Nothing exported.",
                    );
                  }}
                  fullWidth
                />
              </View>
            </Card>

            <Card>
              <View style={{ flexDirection: "row", gap: 10 }}>
                <View
                  style={[
                    styles.exportIcon,
                    { backgroundColor: c.primarySoft, borderColor: c.primarySoftBorder },
                  ]}
                >
                  <Ionicons name="folder-open-outline" size={18} color={c.violet} />
                </View>
                <View style={{ flex: 1 }}>
                  <Text style={[styles.fieldTitle, { color: c.text, marginBottom: 2 }]}>
                    Download Live Source Code
                  </Text>
                  <Text style={[styles.fieldHint, { color: c.textMuted }]}>
                    Every file of THIS app — {sourceSummary.fileCount} files ·{" "}
                    {(sourceSummary.totalBytes / 1024).toFixed(1)} KB · one-click
                  </Text>
                </View>
              </View>
              <View style={{ marginTop: 12 }}>
                <PrimaryButton
                  label={exporting === "source" ? "Preparing…" : "↓ Download All Source Code"}
                  icon="cloud-download-outline"
                  variant="outline"
                  loading={exporting === "source"}
                  onPress={async () => {
                    setExporting("source");
                    const r = await exportSourceCode();
                    setExporting(null);
                    Alert.alert(
                      r.ok ? "Source ready" : "Export failed",
                      r.ok
                        ? `${r.message}\n\nExtract with the one-liner inside the file.`
                        : r.message,
                    );
                  }}
                  fullWidth
                />
              </View>
              <Text
                style={{
                  textAlign: "center",
                  color: c.textDim,
                  fontFamily: "Inter_400Regular",
                  fontSize: 11,
                  marginTop: 6,
                }}
              >
                Bundle generated {new Date(sourceSummary.generatedAt).toLocaleString()}
              </Text>
            </Card>

            <Card>
              <View style={{ flexDirection: "row", gap: 10, alignItems: "center" }}>
                <Ionicons name="logo-github" size={18} color={c.text} />
                <Text style={[styles.fieldTitle, { color: c.text, marginBottom: 0 }]}>
                  Push Projects to GitHub
                </Text>
              </View>
              <Text style={[styles.fieldHint, { color: c.textMuted, marginTop: 6 }]}>
                Target: {settings.githubRepo || "(set repo in AI Settings)"} ·{" "}
                Token: {settings.githubToken ? "configured" : "missing"}
              </Text>
              {pushCandidates.length === 0 ? (
                <Text style={{ color: c.textDim, fontSize: 12, marginTop: 12, fontFamily: "Inter_400Regular" }}>
                  No projects ready to push yet.
                </Text>
              ) : (
                <View style={{ gap: 8, marginTop: 12 }}>
                  {pushingId && pushProgress ? (
                    <View
                      style={{
                        flexDirection: "row",
                        alignItems: "center",
                        gap: 8,
                        paddingHorizontal: 12,
                        paddingVertical: 8,
                        borderRadius: 8,
                        backgroundColor: c.primarySoft,
                      }}
                    >
                      <Ionicons name="cloud-upload-outline" size={14} color={c.violet} />
                      <Text
                        style={{
                          flex: 1,
                          color: c.violet,
                          fontFamily: "Inter_400Regular",
                          fontSize: 12,
                        }}
                        numberOfLines={1}
                      >
                        {pushProgress}
                      </Text>
                    </View>
                  ) : null}
                  {pushCandidates.map((p) => (
                    <View
                      key={p.id}
                      style={{
                        flexDirection: "row",
                        alignItems: "center",
                        gap: 10,
                        paddingVertical: 8,
                        borderTopWidth: 1,
                        borderTopColor: c.cardBorderSubtle,
                      }}
                    >
                      <View style={{ flex: 1 }}>
                        <Text style={{ color: c.text, fontFamily: "Inter_600SemiBold", fontSize: 13 }}>
                          {p.name}
                        </Text>
                        <Text style={{ color: c.textMuted, fontFamily: "Inter_400Regular", fontSize: 11 }}>
                          {p.platform.toUpperCase()} · {p.status}
                        </Text>
                      </View>
                      <Pressable
                        onPress={async () => {
                          if (!settings.githubToken.trim() || !settings.githubRepo.trim()) {
                            Alert.alert(
                              "Configure GitHub first",
                              "Set token + repo on the AI Settings tab.",
                            );
                            return;
                          }
                          setPushingId(p.id);
                          setPushProgress("");
                          const r = await pushToGithub(p.id, (msg) => setPushProgress(msg));
                          setPushingId(null);
                          setPushProgress("");
                          Alert.alert(
                            r.ok ? "Pushed to GitHub" : "Push failed",
                            r.ok && r.url
                              ? `${r.message}\n\n${r.url}`
                              : r.message,
                          );
                        }}
                        style={{
                          flexDirection: "row",
                          alignItems: "center",
                          gap: 6,
                          paddingHorizontal: 12,
                          paddingVertical: 8,
                          borderRadius: 8,
                          backgroundColor: pushingId === p.id ? c.cardSubtle : c.primary,
                          opacity: pushingId === p.id ? 0.7 : 1,
                        }}
                      >
                        <Ionicons name="cloud-upload-outline" size={14} color={c.text} />
                        <Text style={{ color: c.text, fontFamily: "Inter_600SemiBold", fontSize: 12 }}>
                          {pushingId === p.id ? "Pushing…" : "Push"}
                        </Text>
                      </Pressable>
                    </View>
                  ))}
                </View>
              )}
            </Card>

            <Card>
              <Text style={[styles.fieldTitle, { color: c.text }]}>Danger zone</Text>
              <Text style={[styles.fieldHint, { color: c.textMuted, marginBottom: 12 }]}>
                Wipe all device data and start fresh.
              </Text>
              <PrimaryButton
                label="Reset Device Storage"
                icon="trash-outline"
                variant="outline"
                onPress={wipeStorage}
                fullWidth
              />
            </Card>
          </>
        ) : null}

        {tab === "infra" ? (
          <>
            <Card>
              <View style={{ flexDirection: "row", alignItems: "center", justifyContent: "space-between" }}>
                <View style={{ flexDirection: "row", alignItems: "center", gap: 8 }}>
                  <Ionicons name="pulse" size={18} color={c.violet} />
                  <Text style={[styles.fieldTitle, { color: c.text, marginBottom: 0 }]}>
                    System Health Check
                  </Text>
                </View>
                <Pressable onPress={runHealthChecks} disabled={healthRunning}>
                  <View
                    style={[
                      styles.runBtn,
                      { backgroundColor: c.primary, opacity: healthRunning ? 0.6 : 1 },
                    ]}
                  >
                    <Ionicons name="play" size={12} color={c.text} />
                    <Text style={{ color: c.text, fontFamily: "Inter_600SemiBold", fontSize: 12 }}>
                      Run Check
                    </Text>
                  </View>
                </Pressable>
              </View>
              <View style={{ marginTop: 14, gap: 0 }}>
                {healthChecks.map((h, i) => (
                  <View
                    key={h.name}
                    style={[
                      styles.healthRow,
                      i < healthChecks.length - 1 && {
                        borderBottomWidth: 1,
                        borderBottomColor: c.cardBorderSubtle,
                      },
                    ]}
                  >
                    <View
                      style={[
                        styles.healthDot,
                        {
                          backgroundColor:
                            h.state === "ok"
                              ? c.green
                              : h.state === "fail"
                                ? c.amber
                                : h.state === "checking"
                                  ? c.cyan
                                  : c.textDim,
                        },
                      ]}
                    />
                    <Text style={[styles.healthLabel, { color: c.text }]}>{h.label}</Text>
                    <Text style={{ color: c.textDim, fontSize: 12, fontFamily: "Inter_400Regular" }}>
                      {h.state === "checking"
                        ? "Checking…"
                        : h.state === "ok"
                          ? "OK"
                          : h.state === "fail"
                            ? "Not configured"
                            : "Not checked"}
                    </Text>
                  </View>
                ))}
              </View>
            </Card>

            <Card>
              <Text style={[styles.sectionLabel, { color: c.textMuted }]}>WORKSPACE INFO</Text>
              <InfoRow label="Projects built" value={String(projects.length)} />
              <InfoRow label="Agent memories" value={String(memoryCount)} />
              <InfoRow label="Primary AI" value="Pollinations AI (Free · No Limits)" />
              <InfoRow label="Fallback AI" value="Groq → Custom Key → Platform" />
              <InfoRow label="Build targets" value="Android SDK 34 · Web · Flutter" />
              <InfoRow label="Architecture" value="MVVM + Clean Architecture + Hilt" />
              <InfoRow label="Offline cache" value="AsyncStorage (device storage)" />
              <InfoRow label="Version" value="Agent Studio v3.0.0" isLast />
            </Card>

            <Card>
              <Text style={[styles.fieldTitle, { color: c.text }]}>Proxy Integration URL</Text>
              <Text style={[styles.fieldHint, { color: c.textMuted }]}>
                Optional self-hosted proxy that forwards agent requests.
              </Text>
              <KeyInput
                value={proxyUrl}
                onChange={setProxyUrl}
                placeholder="https://your-proxy.example/api"
                masked={false}
              />
              <Text style={[styles.fieldTitle, { color: c.text, marginTop: 16 }]}>
                API Key Auth Header
              </Text>
              <KeyInput
                value={authHeader}
                onChange={setAuthHeader}
                placeholder="Bearer …"
                masked={false}
              />
              <View style={{ marginTop: 12 }}>
                <PrimaryButton
                  label="Save Infrastructure"
                  icon="save-outline"
                  onPress={() => updateSettings({ proxyUrl, authorizationHeader: authHeader })}
                  fullWidth
                />
              </View>
            </Card>
          </>
        ) : null}
      </ScrollView>

      <SideMenu visible={menuOpen} onClose={() => setMenuOpen(false)} />
    </View>
  );
}

