import { Ionicons } from "@expo/vector-icons";
import { useRouter } from "expo-router";
import React, { useMemo, useState } from "react";
import {
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  View,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { AgentBadge } from "@/components/AgentBadge";
import { Card } from "@/components/Card";
import { Pill } from "@/components/Pill";
import { PrimaryButton } from "@/components/PrimaryButton";
import { ScreenHeader } from "@/components/ScreenHeader";
import { SideMenu } from "@/components/SideMenu";
import { useStudio } from "@/contexts/StudioContext";
import { useColors } from "@/hooks/useColors";
import { PIPELINE, TEAMS } from "@/lib/seed";
import type { Platform } from "@/lib/types";

const STEP_LABELS = ["STEP 1", "STEP 2", "STEP 3", "STEP 4", "STEP 5"];
const STEP_TONES: ("amber" | "muted" | "violet" | "green" | "amber")[] = [
  "amber",
  "muted",
  "violet",
  "green",
  "amber",
];

export default function StudioScreen() {
  const c = useColors();
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const { settings, updateSettings, startBuild } = useStudio();
  const [menuOpen, setMenuOpen] = useState(false);
  const [description, setDescription] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const team = useMemo(
    () => TEAMS.find((t) => t.id === settings.selectedTeam) ?? TEAMS[0],
    [settings.selectedTeam],
  );

  const onBuild = async () => {
    if (!description.trim() || !team) return;
    setSubmitting(true);
    try {
      const id = await startBuild({
        description: description.trim(),
        platform: team.id as Platform,
      });
      setDescription("");
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      router.push(`/build/${id}` as any);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <View style={{ flex: 1, backgroundColor: c.bg }}>
      <ScreenHeader
        title="Studio"
        subtitle="Smart Auto-Routing"
        showMenu
        onMenuPress={() => setMenuOpen(true)}
      />

      <ScrollView
        contentContainerStyle={{
          padding: 16,
          paddingBottom: insets.bottom + 140,
          gap: 16,
        }}
      >
        <Card style={{ backgroundColor: c.greenSoft, borderColor: c.greenBorder }}>
          <View style={{ flexDirection: "row", gap: 10 }}>
            <Ionicons name="flash" size={18} color={c.green} style={{ marginTop: 2 }} />
            <View style={{ flex: 1 }}>
              <Text style={[styles.calloutTitle, { color: c.green }]}>
                Smart Auto-Routing
              </Text>
              <Text style={[styles.calloutBody, { color: c.textSecondary }]}>
                Just describe your app in plain English. The system automatically
                selects the right agent team — you never need to choose manually.
              </Text>
            </View>
          </View>
        </Card>

        {/* Team selector */}
        <ScrollView horizontal showsHorizontalScrollIndicator={false}>
          <View style={{ flexDirection: "row", gap: 10 }}>
            {TEAMS.map((t) => {
              const active = settings.selectedTeam === t.id;
              return (
                <Pressable
                  key={t.id}
                  onPress={() => updateSettings({ selectedTeam: t.id })}
                >
                  <View
                    style={[
                      styles.teamChip,
                      {
                        backgroundColor: active ? `${t.color}22` : c.cardSubtle,
                        borderColor: active ? t.color : c.cardBorder,
                      },
                    ]}
                  >
                    <Ionicons
                      name={t.icon as keyof typeof Ionicons.glyphMap}
                      size={16}
                      color={active ? t.color : c.textSecondary}
                    />
                    <Text
                      style={{
                        color: active ? t.color : c.textSecondary,
                        fontFamily: "Inter_600SemiBold",
                        fontSize: 13,
                      }}
                    >
                      {t.name}
                    </Text>
                  </View>
                </Pressable>
              );
            })}
          </View>
        </ScrollView>

        {/* Selected team detail */}
        {team ? (
          <Card>
            <View style={styles.teamDetail}>
              <Ionicons
                name={team.icon as keyof typeof Ionicons.glyphMap}
                size={18}
                color={team.color}
              />
              <Text style={[styles.teamName, { color: c.text }]}>{team.name}</Text>
            </View>
            <Text style={[styles.teamDesc, { color: c.textMuted }]}>
              {team.description}
            </Text>
            <View style={{ flexDirection: "row", flexWrap: "wrap", gap: 6, marginTop: 10 }}>
              <Text
                style={{
                  width: "100%",
                  color: c.textDim,
                  fontFamily: "Inter_500Medium",
                  fontSize: 11,
                }}
              >
                Auto-selected when you say:
              </Text>
              {team.autoTags.map((tag) => (
                <View
                  key={tag}
                  style={[
                    styles.tag,
                    { backgroundColor: c.cardSubtle, borderColor: c.cardBorder },
                  ]}
                >
                  <Text style={{ color: c.textSecondary, fontSize: 12 }}>{tag}</Text>
                </View>
              ))}
            </View>
          </Card>
        ) : null}

        {/* Pipeline list */}
        <View style={{ gap: 10 }}>
          {PIPELINE.map((p, idx) => (
            <Card key={p.role} style={styles.pipelineRow}>
              <AgentBadge
                color={p.color}
                soft={p.soft}
                icon={p.icon}
                iconLib={p.iconLib}
                size={42}
              />
              <View style={{ flex: 1 }}>
                <View style={{ flexDirection: "row", alignItems: "center", gap: 8 }}>
                  <Text style={[styles.agentName, { color: c.text }]}>{p.name}</Text>
                  <Pill
                    label={STEP_LABELS[idx] || `STEP ${idx + 1}`}
                    tone={STEP_TONES[idx] || "muted"}
                  />
                </View>
                <Text
                  style={[styles.agentDesc, { color: c.textMuted }]}
                  numberOfLines={2}
                >
                  {p.description}
                </Text>
              </View>
              <Ionicons name="chevron-down" size={18} color={c.textDim} />
            </Card>
          ))}
        </View>

        {/* Build form */}
        <Card>
          <Text style={[styles.cardLabel, { color: c.textMuted }]}>DESCRIBE YOUR APP</Text>
          <View
            style={[
              styles.input,
              { borderColor: c.cardBorder, backgroundColor: c.bgElevated },
            ]}
          >
            <TextInput
              value={description}
              onChangeText={setDescription}
              placeholder="Describe your app — agents will plan, build, test and package it..."
              placeholderTextColor={c.textDim}
              multiline
              style={{
                color: c.text,
                fontFamily: "Inter_400Regular",
                fontSize: 14,
                minHeight: 90,
                textAlignVertical: "top",
              }}
            />
          </View>
          <PrimaryButton
            label={submitting ? "Starting build…" : `Start a Build with ${team?.name ?? "Team"}`}
            icon="sparkles"
            onPress={onBuild}
            loading={submitting}
            disabled={!description.trim()}
            variant="success"
            fullWidth
          />
        </Card>
      </ScrollView>

      <SideMenu visible={menuOpen} onClose={() => setMenuOpen(false)} />
    </View>
  );
}

