const STEP_TONES: ("amber" | "muted" | "violet" | "green" | "amber")[] = [
  "amber",
  "muted",
  "violet",
  "green",
  "amber",
];

export default function AgentsScreen() {
  const c = useColors();
  const insets = useSafeAreaInsets();
  const { settings, updateSettings } = useStudio();
  const [expanded, setExpanded] = useState<string | null>("architect");

  const team = TEAMS.find((t) => t.id === settings.selectedTeam) ?? TEAMS[0];

  return (
    <View style={{ flex: 1, backgroundColor: c.bg }}>
      <ScreenHeader title="Agents" showBack />
      <ScrollView
        contentContainerStyle={{
          padding: 16,
          paddingBottom: insets.bottom + 40,
          gap: 14,
        }}
      >
        <Text style={[styles.subtitle, { color: c.textMuted }]}>
          Meet your specialist teams. The system picks the right team automatically based on what you describe.
        </Text>

        <Card style={{ backgroundColor: c.greenSoft, borderColor: c.greenBorder }}>
          <View style={{ flexDirection: "row", gap: 10 }}>
            <Ionicons name="flash" size={18} color={c.green} style={{ marginTop: 2 }} />
            <View style={{ flex: 1 }}>
              <Text style={{ color: c.green, fontFamily: "Inter_700Bold", fontSize: 14 }}>
                Smart Auto-Routing
              </Text>
              <Text style={{ color: c.textSecondary, fontFamily: "Inter_400Regular", fontSize: 12, lineHeight: 18, marginTop: 4 }}>
                Just describe your app in plain English. The system automatically selects the right agent team — you never need to choose manually.
              </Text>
            </View>
          </View>
        </Card>

        {/* Teams */}
        <ScrollView horizontal showsHorizontalScrollIndicator={false}>
          <View style={{ flexDirection: "row", gap: 10 }}>
            {TEAMS.map((t) => {
              const active = settings.selectedTeam === t.id;
              return (
                <Pressable key={t.id} onPress={() => updateSettings({ selectedTeam: t.id })}>
                  <View
                    style={[
                      styles.teamChip,
                      {
                        backgroundColor: active ? `${t.color}22` : c.cardSubtle,
                        borderColor: active ? t.color : c.cardBorder,
                      },
                    ]}
                  >
                    <Ionicons
                      name={t.icon as keyof typeof Ionicons.glyphMap}
                      size={16}
                      color={active ? t.color : c.textSecondary}
                    />
                    <Text
                      style={{
                        color: active ? t.color : c.textSecondary,
                        fontFamily: "Inter_600SemiBold",
                        fontSize: 13,
                      }}
                    >
                      {t.name}
                    </Text>
                  </View>
                </Pressable>
              );
            })}
          </View>
        </ScrollView>

        {team ? (
          <Card>
            <View style={{ flexDirection: "row", alignItems: "center", gap: 8 }}>
              <Ionicons
                name={team.icon as keyof typeof Ionicons.glyphMap}
                size={18}
                color={team.color}
              />
              <Text style={{ color: c.text, fontFamily: "Inter_700Bold", fontSize: 16 }}>
                {team.name}
              </Text>
            </View>
            <Text style={{ color: c.textMuted, fontFamily: "Inter_400Regular", fontSize: 12, lineHeight: 18, marginTop: 6 }}>
              {team.description}
            </Text>
            <View style={{ marginTop: 10 }}>
              <Text style={{ color: c.textDim, fontSize: 11, fontFamily: "Inter_500Medium", marginBottom: 8 }}>
                Auto-selected when you say:
              </Text>
              <View style={{ flexDirection: "row", flexWrap: "wrap", gap: 6 }}>
                {team.autoTags.map((t) => (
                  <View
                    key={t}
                    style={[
                      styles.tag,
                      { backgroundColor: c.cardSubtle, borderColor: c.cardBorder },
                    ]}
                  >
                    <Text style={{ color: c.textSecondary, fontSize: 12 }}>{t}</Text>
                  </View>
                ))}
              </View>
            </View>
          </Card>
        ) : null}

        {/* Pipeline list, expandable */}
        <View style={{ gap: 10 }}>
          {PIPELINE.map((p, idx) => {
            const open = expanded === p.role;
            return (
              <Card key={p.role} padded={false}>
                <Pressable
                  onPress={() => setExpanded(open ? null : p.role)}
                  style={styles.expandRow}
                >
                  <AgentBadge color={p.color} soft={p.soft} icon={p.icon} iconLib={p.iconLib} size={42} />
                  <View style={{ flex: 1 }}>
                    <View style={{ flexDirection: "row", alignItems: "center", gap: 8 }}>
                      <Text style={{ color: c.text, fontFamily: "Inter_700Bold", fontSize: 14 }}>
                        {p.name}
                      </Text>
                      <Pill label={STEP_LABELS[idx] || `STEP ${idx + 1}`} tone={STEP_TONES[idx] || "muted"} />
                    </View>
                    <Text
                      style={{
                        color: c.textMuted,
                        fontFamily: "Inter_400Regular",
                        fontSize: 12,
                        marginTop: 4,
                      }}
                      numberOfLines={open ? undefined : 1}
                    >
                      {p.description}
                    </Text>
                  </View>
                  <Ionicons
                    name={open ? "chevron-up" : "chevron-down"}
                    size={18}
                    color={c.textDim}
                  />
                </Pressable>
                {open ? (
                  <View
                    style={[
                      styles.expandBody,
                      { borderTopColor: c.cardBorderSubtle },
                    ]}
                  >
                    <Text style={{ color: c.textMuted, fontSize: 12, fontFamily: "Inter_400Regular", lineHeight: 18 }}>
                      {expandedDetail(p.role)}
                    </Text>
                  </View>
                ) : null}
              </Card>
            );
          })}
        </View>
      </ScrollView>
    </View>
  );
}

function expandedDetail(role: string) {
  switch (role) {
    case "architect":
      return "Plans the entire app structure before any code is written. Decides on packages, modules, data models, and navigation.";
    case "builder":
      return "Writes all core source files using trained patterns from the Memory bank. Skips boilerplate by reusing learned snippets.";
    case "designer":
      return "Creates layouts, themes, and component code. Pulls Material 3 / Tailwind / Cupertino tokens from the Knowledge Library.";
    case "qa":
      return "Reviews everything for null safety, error handling, and missing tests. Files issues back to the Builder agent.";
    case "packager":
      return "Finalizes the build manifest, signs the output, confirms artifact integrity, and reports READY TO SHIP.";
    default:
      return "";
  }
}

