import { Ionicons } from "@expo/vector-icons";
import { useRouter } from "expo-router";
import React, { useState } from "react";
import {
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  View,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { Card } from "@/components/Card";
import { PrimaryButton } from "@/components/PrimaryButton";
import { ScreenHeader } from "@/components/ScreenHeader";
import { useStudio } from "@/contexts/StudioContext";
import { useColors } from "@/hooks/useColors";
import { TEAMS } from "@/lib/seed";
import type { Platform } from "@/lib/types";

const SUGGESTIONS = [
  "todo app with reminders",
  "AI chatbot with memory",
  "weather dashboard",
  "fitness tracker",
  "habit streak tracker",
  "expense tracker",
];

export default function NewBuildScreen() {
  const c = useColors();
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const { startBuild } = useStudio();
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [platform, setPlatform] = useState<Platform>("android");
  const [submitting, setSubmitting] = useState(false);

  const start = async () => {
    if (!description.trim()) return;
    setSubmitting(true);
    try {
      const id = await startBuild({
        description: description.trim(),
        platform,
        name: name.trim() || undefined,
      });
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      router.replace(`/build/${id}` as any);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <View style={{ flex: 1, backgroundColor: c.bg }}>
      <ScreenHeader title="New Build" showBack />
      <ScrollView
        contentContainerStyle={{
          padding: 16,
          paddingBottom: insets.bottom + 40,
          gap: 14,
        }}
        keyboardShouldPersistTaps="handled"
      >
        <Card>
          <Text style={[styles.label, { color: c.textMuted }]}>PROJECT NAME (optional)</Text>
          <View
            style={[styles.input, { backgroundColor: c.bgElevated, borderColor: c.cardBorder }]}
          >
            <TextInput
              value={name}
              onChangeText={setName}
              placeholder="My App"
              placeholderTextColor={c.textDim}
              style={{
                color: c.text,
                fontFamily: "Inter_400Regular",
                fontSize: 14,
                height: 40,
              }}
            />
          </View>

          <Text style={[styles.label, { color: c.textMuted, marginTop: 16 }]}>
            DESCRIBE YOUR APP
          </Text>
          <View
            style={[
              styles.input,
              {
                backgroundColor: c.bgElevated,
                borderColor: c.cardBorder,
                paddingVertical: 10,
              },
            ]}
          >
            <TextInput
              value={description}
              onChangeText={setDescription}
              placeholder="A todo app with categories, dark mode, and reminders…"
              placeholderTextColor={c.textDim}
              multiline
              style={{
                color: c.text,
                fontFamily: "Inter_400Regular",
                fontSize: 14,
                minHeight: 110,
                textAlignVertical: "top",
              }}
            />
          </View>

          <Text style={[styles.label, { color: c.textMuted, marginTop: 16 }]}>TARGET PLATFORM</Text>
          <View style={{ flexDirection: "row", gap: 8, marginTop: 8 }}>
            {TEAMS.map((t) => {
              const active = platform === t.id;
              return (
                <Pressable
                  key={t.id}
                  onPress={() => setPlatform(t.id)}
                  style={{ flex: 1 }}
                >
                  <View
                    style={[
                      styles.platChip,
                      {
                        backgroundColor: active ? `${t.color}22` : c.cardSubtle,
                        borderColor: active ? t.color : c.cardBorder,
                      },
                    ]}
                  >
                    <Ionicons
                      name={t.icon as keyof typeof Ionicons.glyphMap}
                      size={16}
                      color={active ? t.color : c.textSecondary}
                    />
                    <Text
                      style={{
                        color: active ? t.color : c.textSecondary,
                        fontFamily: "Inter_600SemiBold",
                        fontSize: 12,
                      }}
                    >
                      {t.name.replace(" Team", "")}
                    </Text>
                  </View>
                </Pressable>
              );
            })}
          </View>
        </Card>

        <Card>
          <Text style={[styles.label, { color: c.textMuted, marginBottom: 8 }]}>
            QUICK IDEAS
          </Text>
          <View style={{ flexDirection: "row", flexWrap: "wrap", gap: 8 }}>
            {SUGGESTIONS.map((s) => (
              <Pressable key={s} onPress={() => setDescription(s)}>
                <View
                  style={[
                    styles.suggestion,
                    { backgroundColor: c.cardSubtle, borderColor: c.cardBorder },
                  ]}
                >
                  <Text style={{ color: c.textSecondary, fontFamily: "Inter_500Medium", fontSize: 12 }}>
                    {s}
                  </Text>
                </View>
              </Pressable>
            ))}
          </View>
        </Card>

        <PrimaryButton
          label={submitting ? "Starting…" : "Build with Pipeline"}
          icon="sparkles"
          onPress={start}
          loading={submitting}
          disabled={!description.trim()}
          fullWidth
        />
      </ScrollView>
    </View>
  );
}

const styles = StyleSheet.create({
  label: {
    fontFamily: "Inter_600SemiBold",
    fontSize: 11,
    letterSpacing: 1,
    marginBottom: 6,
  },
