import { ScreenHeader } from "@/components/ScreenHeader";
import { useStudio } from "@/contexts/StudioContext";
import { useColors } from "@/hooks/useColors";

export default function ProjectsScreen() {
  const c = useColors();
  const router = useRouter();
  const insets = useSafeAreaInsets();
  const { projects, deleteProject } = useStudio();

  const fmtDate = (ts: number) => {
    const d = new Date(ts);
    return d.toLocaleDateString(undefined, { month: "short", day: "numeric" }) +
      " · " + d.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
  };

  return (
    <View style={{ flex: 1, backgroundColor: c.bg }}>
      <ScreenHeader title="Projects" showBack />
      <ScrollView
        contentContainerStyle={{
          padding: 16,
          paddingBottom: insets.bottom + 40,
          gap: 12,
        }}
      >
        {projects.length === 0 ? (
          <Card style={{ alignItems: "center", paddingVertical: 36 }}>
            <Ionicons name="folder-open-outline" size={36} color={c.textDim} />
            <Text style={{ color: c.text, fontFamily: "Inter_700Bold", fontSize: 16, marginTop: 12 }}>
              No projects yet
            </Text>
            <Text
              style={{
                color: c.textMuted,
                fontFamily: "Inter_400Regular",
                fontSize: 13,
                textAlign: "center",
                marginTop: 6,
                marginBottom: 18,
              }}
            >
              Start your first build from the Studio tab.
            </Text>
            <PrimaryButton
              label="Start a Build"
              icon="sparkles"
              onPress={() => router.push("/new-build")}
            />
          </Card>
        ) : (
          projects.map((p) => (
            <Pressable
              key={p.id}
              // eslint-disable-next-line @typescript-eslint/no-explicit-any
              onPress={() => router.push(`/build/${p.id}` as any)}
            >
              <Card>
                <View style={styles.row}>
                  <View
                    style={[
                      styles.icon,
                      { backgroundColor: c.cardSubtle, borderColor: c.cardBorder },
                    ]}
                  >
                    <Ionicons
                      name={
                        p.platform === "android"
                          ? "phone-portrait-outline"
                          : p.platform === "web"
                            ? "globe-outline"
                            : "heart"
                      }
                      size={20}
                      color={c.violet}
                    />
                  </View>
                  <View style={{ flex: 1 }}>
                    <Text style={[styles.name, { color: c.text }]} numberOfLines={1}>
                      {p.name}
                    </Text>
                    <Text style={[styles.desc, { color: c.textMuted }]} numberOfLines={2}>
                      {p.description}
                    </Text>
                    <View style={{ flexDirection: "row", gap: 6, marginTop: 6, alignItems: "center" }}>
                      <Pill
                        label={p.status === "ready" ? "READY" : p.status === "building" ? "BUILDING" : "FAILED"}
                        tone={p.status === "ready" ? "green" : p.status === "building" ? "amber" : "primary"}
                      />
                      <Text style={{ color: c.textDim, fontSize: 11, fontFamily: "Inter_500Medium" }}>
                        {fmtDate(p.updatedAt)}
                      </Text>
                    </View>
                  </View>
                  <Pressable
                    hitSlop={8}
                    onPress={(e) => {
                      e.stopPropagation();
                      Alert.alert("Delete project?", p.name, [
                        { text: "Cancel" },
                        {
                          text: "Delete",
                          style: "destructive",
                          onPress: () => deleteProject(p.id),
                        },
                      ]);
                    }}
                  >
                    <Ionicons name="ellipsis-horizontal" size={18} color={c.textDim} />
                  </Pressable>
                </View>
              </Card>
            </Pressable>
          ))
        )}
      </ScrollView>
    </View>
  );
}

