import { Ionicons, MaterialCommunityIcons } from "@expo/vector-icons";
import React, { useMemo, useState } from "react";
import {
  ActivityIndicator,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";

import { Card } from "@/components/Card";
import { Pill } from "@/components/Pill";
import { PrimaryButton } from "@/components/PrimaryButton";
import { ScreenHeader } from "@/components/ScreenHeader";
import { useStudio } from "@/contexts/StudioContext";
import { useColors } from "@/hooks/useColors";
import { TRAINING_MODULES } from "@/lib/seed";

export default function TrainingScreen() {
  const c = useColors();
  const insets = useSafeAreaInsets();
  const { trainedLessons, trainLesson, trainModule, resetTraining } = useStudio();
  const [busyKey, setBusyKey] = useState<string | null>(null);

  const totalLessons = TRAINING_MODULES.reduce(
    (acc, m) => acc + m.lessons.length,
    0,
  );
  const trainedCount = useMemo(
    () =>
      TRAINING_MODULES.reduce(
        (acc, m) =>
          acc +
          m.lessons.filter((l) => trainedLessons[`${m.id}:${l.id}`]).length,
        0,
      ),
    [trainedLessons],
  );

  const pct = Math.round((trainedCount / Math.max(1, totalLessons)) * 100);

  const handleLessonTrain = async (moduleId: string, lessonId: string) => {
    const key = `${moduleId}:${lessonId}`;
    setBusyKey(key);
    try {
      await trainLesson(moduleId, lessonId);
    } finally {
      setBusyKey(null);
    }
  };

  const handleModuleTrain = async (moduleId: string) => {
    setBusyKey(`mod:${moduleId}`);
    try {
      await trainModule(moduleId);
    } finally {
      setBusyKey(null);
    }
  };

  return (
    <View style={{ flex: 1, backgroundColor: c.bg }}>
      <ScreenHeader title="Agent Training" showBack />
      <ScrollView
        contentContainerStyle={{
          padding: 16,
          paddingBottom: insets.bottom + 40,
          gap: 14,
        }}
      >
        <View style={{ flexDirection: "row", alignItems: "center", gap: 10 }}>
          <Ionicons name="school-outline" size={22} color={c.violet} />
          <View style={{ flex: 1 }}>
            <Text style={{ color: c.text, fontFamily: "Inter_700Bold", fontSize: 18 }}>
              Agent Training
            </Text>
            <Text style={{ color: c.textMuted, fontFamily: "Inter_400Regular", fontSize: 12, marginTop: 2 }}>
              Tap any lesson to silently train agents. Knowledge saves to Agent Memory automatically.
            </Text>
          </View>
        </View>

        <Card>
          <View style={{ flexDirection: "row", justifyContent: "space-between", alignItems: "center" }}>
            <View style={{ flexDirection: "row", alignItems: "center", gap: 8 }}>
              <Ionicons name="trophy-outline" size={18} color={c.amber} />
              <Text style={{ color: c.text, fontFamily: "Inter_700Bold", fontSize: 14 }}>
                Memory Bank
              </Text>
            </View>
            <Text style={{ color: c.text, fontFamily: "Inter_700Bold", fontSize: 14 }}>
              {trainedCount}/{totalLessons} trained
            </Text>
          </View>
          <View
            style={[styles.progressTrack, { backgroundColor: c.cardSubtle, marginTop: 12 }]}
          >
            <View
              style={[
                styles.progressFill,
                { backgroundColor: c.violet, width: `${pct}%` },
              ]}
            />
          </View>
          <View style={{ flexDirection: "row", justifyContent: "space-between", marginTop: 8 }}>
            <Text style={{ color: c.textMuted, fontFamily: "Inter_500Medium", fontSize: 12 }}>
              {pct}% complete
            </Text>
            <Pressable onPress={resetTraining} hitSlop={6} style={{ flexDirection: "row", alignItems: "center", gap: 4 }}>
              <Ionicons name="refresh" size={12} color={c.violet} />
              <Text style={{ color: c.violet, fontFamily: "Inter_600SemiBold", fontSize: 12 }}>
                Reset
              </Text>
            </Pressable>
          </View>
        </Card>

        <Card style={{ backgroundColor: c.primarySoft, borderColor: c.primarySoftBorder }}>
          <View style={{ flexDirection: "row", gap: 10 }}>
            <Ionicons name="flash" size={18} color={c.violet} style={{ marginTop: 2 }} />
            <View style={{ flex: 1 }}>
              <Text style={{ color: c.violet, fontFamily: "Inter_700Bold", fontSize: 14 }}>
                One-Click Silent Learning
              </Text>
              <Text style={{ color: c.textSecondary, fontFamily: "Inter_400Regular", fontSize: 12, lineHeight: 18, marginTop: 4 }}>
                Click a lesson → AI fetches knowledge in background → Saves to Agent Memory automatically. No reading required. Agents use these memories in every build.
              </Text>
            </View>
          </View>
        </Card>

        {TRAINING_MODULES.map((m) => {
          const lessonsTrained = m.lessons.filter(
            (l) => trainedLessons[`${m.id}:${l.id}`],
          ).length;
          const allTrained = lessonsTrained === m.lessons.length;
          return (
            <Card key={m.id}>
              <View style={{ flexDirection: "row", gap: 12 }}>
                <View
                  style={[
                    styles.moduleIcon,
                    { backgroundColor: `${m.agentColor}22`, borderColor: m.agentColor },
                  ]}
                >
                  <Ionicons
                    name={m.icon as keyof typeof Ionicons.glyphMap}
                    size={20}
                    color={m.agentColor}
                  />
                </View>
                <View style={{ flex: 1 }}>
                  <Text style={{ color: c.text, fontFamily: "Inter_700Bold", fontSize: 15 }}>
                    {m.title}
                  </Text>
                  <Text style={{ color: c.textMuted, fontFamily: "Inter_400Regular", fontSize: 12, marginTop: 4, lineHeight: 17 }}>
                    {m.description}
                  </Text>
                </View>
                <View style={{ alignItems: "flex-end", gap: 6 }}>
                  <View
                    style={[
                      styles.agentChip,
                      { backgroundColor: `${m.agentColor}22`, borderColor: m.agentColor },
                    ]}
                  >
                    <Text style={{ color: m.agentColor, fontFamily: "Inter_600SemiBold", fontSize: 10 }}>
                      {m.agent}
                    </Text>
                  </View>
                  <Pressable
                    onPress={() => handleModuleTrain(m.id)}
                    disabled={allTrained || busyKey === `mod:${m.id}`}
                  >
                    <View
                      style={[
                        styles.trainAllBtn,
                        {
                          backgroundColor: allTrained ? c.greenSoft : c.primarySoft,
                          borderColor: allTrained ? c.greenBorder : c.primarySoftBorder,
                        },
                      ]}
                    >
                      <Text
                        style={{
                          color: allTrained ? c.green : c.violet,
                          fontFamily: "Inter_600SemiBold",
                          fontSize: 11,
                        }}
                      >
