import React from "react";
import { StyleSheet, Text, View } from "react-native";

import { useColors } from "@/hooks/useColors";

interface Props {
  text: string;
}

// Lightweight markdown-ish renderer: headings, bullets, code fences, paragraphs.
export function Markdown({ text }: Props) {
  const c = useColors();
  const lines = text.replace(/\r\n/g, "\n").split("\n");
  const blocks: React.ReactNode[] = [];
  let inCode = false;
  let codeBuf: string[] = [];
  let listBuf: string[] = [];

  const flushList = (key: string) => {
    if (listBuf.length === 0) return;
    blocks.push(
      <View key={`list-${key}`} style={{ marginVertical: 6, gap: 4 }}>
        {listBuf.map((item, i) => (
          <View key={i} style={styles.li}>
            <Text style={[styles.bullet, { color: c.violet }]}>•</Text>
            <Text style={[styles.body, { color: c.textSecondary }]}>{item}</Text>
          </View>
        ))}
      </View>,
    );
    listBuf = [];
  };

  const flushCode = (key: string) => {
    if (codeBuf.length === 0) return;
    blocks.push(
      <View
        key={`code-${key}`}
        style={[
          styles.code,
          { backgroundColor: c.bgElevated, borderColor: c.cardBorder },
        ]}
      >
        <Text style={[styles.codeText, { color: c.cyan }]} selectable>
          {codeBuf.join("\n")}
        </Text>
      </View>,
    );
    codeBuf = [];
  };

  lines.forEach((raw, i) => {
    const line = raw;
    if (line.trim().startsWith("```")) {
      if (inCode) {
        flushCode(String(i));
      }
      inCode = !inCode;
      return;
    }
    if (inCode) {
      codeBuf.push(line);
      return;
    }
    if (/^#{1,6}\s/.test(line)) {
      flushList(String(i));
      const level = (line.match(/^#+/) || ["#"])[0].length;
      const t = line.replace(/^#+\s*/, "");
      blocks.push(
        <Text
          key={`h-${i}`}
          style={[
            styles.heading,
            {
              color: c.text,
              fontSize: level === 1 ? 18 : level === 2 ? 16 : 14,
              marginTop: 10,
              marginBottom: 4,
            },
          ]}
        >
          {t}
        </Text>,
      );
      return;
    }
    if (/^\s*[-*]\s+/.test(line)) {
      listBuf.push(line.replace(/^\s*[-*]\s+/, ""));
      return;
    }
    if (line.trim() === "") {
      flushList(String(i));
      return;
    }
    flushList(String(i));
    blocks.push(
      <Text key={`p-${i}`} style={[styles.body, { color: c.textSecondary }]}>
        {line}
      </Text>,
    );
  });

  flushList("end");
  flushCode("end");

  return <View style={{ gap: 4 }}>{blocks}</View>;
}

