        <ActivityIndicator color={colorFg} size="small" />
      ) : icon ? (
        <Ionicons name={icon} size={small ? 14 : 18} color={colorFg} />
      ) : null}
      <Text
        style={[
          styles.label,
          { color: colorFg, fontSize: small ? 13 : 15 },
        ]}
      >
        {label}
      </Text>
    </View>
  );

  if (isPrimary) {
    return (
      <Pressable onPress={handlePress} disabled={disabled || loading}>
        <LinearGradient
          colors={[c.primary, c.primaryDark]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={[
            styles.base,
            { borderRadius: c.radius, opacity: disabled ? 0.5 : 1 },
          ]}
        >
          {inner}
        </LinearGradient>
      </Pressable>
    );
  }

  if (isSuccess) {
    return (
      <Pressable
        onPress={handlePress}
        disabled={disabled || loading}
        style={[
          styles.base,
          {
            backgroundColor: c.greenSoft,
            borderRadius: c.radius,
            borderWidth: 1,
            borderColor: c.greenBorder,
            opacity: disabled ? 0.5 : 1,
          },
        ]}
      >
        <View style={[styles.inner, heightStyle]}>
          {loading ? (
            <ActivityIndicator color={c.green} size="small" />
          ) : icon ? (
            <Ionicons name={icon} size={18} color={c.green} />
          ) : null}
          <Text style={[styles.label, { color: c.green }]}>{label}</Text>
        </View>
      </Pressable>
    );
  }

  return (
    <Pressable
      onPress={handlePress}
      disabled={disabled || loading}
      style={[
        styles.base,
        {
          backgroundColor: isOutline ? "transparent" : c.cardSubtle,
          borderRadius: c.radius,
          borderWidth: 1,
          borderColor: isOutline ? c.primarySoftBorder : c.cardBorder,
          opacity: disabled ? 0.5 : 1,
        },
      ]}
    >
      {inner}
    </Pressable>
  );
}

