interface Ctx {
  ready: boolean;
  projects: Project[];
  memories: MemoryEntry[];
  knowledge: KnowledgeEntry[];
  settings: AppSettings;
  trainedLessons: Record<string, boolean>;
  proposals: UpgradeProposal[];
