  addKnowledge: (k: Omit<KnowledgeEntry, "id" | "createdAt">) => Promise<void>;
  removeKnowledge: (id: string) => Promise<void>;

  updateSettings: (patch: Partial<AppSettings>) => Promise<void>;

  trainLesson: (moduleId: string, lessonId: string) => Promise<void>;
  trainModule: (moduleId: string) => Promise<void>;
  resetTraining: () => Promise<void>;

  analyzeForUpgrades: () => Promise<UpgradeProposal[]>;
  applyUpgrade: (proposalId: string) => Promise<{ ok: boolean; message: string }>;
  rollbackUpgrade: (snapshotId: string) => Promise<{ ok: boolean; message: string }>;
  dismissProposal: (proposalId: string) => Promise<void>;
}

const StudioContext = createContext<Ctx | null>(null);

const MAX_SNAPSHOTS = 8;

export function StudioProvider({ children }: { children: React.ReactNode }) {
  const [ready, setReady] = useState(false);
  const [projects, setProjects] = useState<Project[]>([]);
  const [memories, setMemories] = useState<MemoryEntry[]>([]);
  const [knowledge, setKnowledge] = useState<KnowledgeEntry[]>([]);
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [trainedLessons, setTrainedLessons] = useState<Record<string, boolean>>(
    {},
  );
  const [proposals, setProposals] = useState<UpgradeProposal[]>([]);
  const [snapshots, setSnapshots] = useState<StudioSnapshot[]>([]);
  const [activeBuildId, setActiveBuildId] = useState<string | null>(null);

  // Mirror state in refs so the orchestrator always reads the latest values.
  const projectsRef = useRef<Project[]>([]);
  const memoriesRef = useRef<MemoryEntry[]>([]);
  const knowledgeRef = useRef<KnowledgeEntry[]>([]);
  const settingsRef = useRef<AppSettings>(DEFAULT_SETTINGS);
  const trainedRef = useRef<Record<string, boolean>>({});

  useEffect(() => {
    projectsRef.current = projects;
  }, [projects]);
  useEffect(() => {
    memoriesRef.current = memories;
  }, [memories]);
  useEffect(() => {
    knowledgeRef.current = knowledge;
  }, [knowledge]);
  useEffect(() => {
    settingsRef.current = settings;
  }, [settings]);
  useEffect(() => {
    trainedRef.current = trainedLessons;
  }, [trainedLessons]);

  useEffect(() => {
    (async () => {
      const [p, m, k, s, t, pr, sn] = await Promise.all([
        loadJSON<Project[]>(STORAGE_KEYS.projects, []),
        loadJSON<MemoryEntry[] | null>(STORAGE_KEYS.memories, null),
        loadJSON<KnowledgeEntry[] | null>(STORAGE_KEYS.knowledge, null),
        loadJSON<AppSettings>(STORAGE_KEYS.settings, DEFAULT_SETTINGS),
        loadJSON<Record<string, boolean>>(STORAGE_KEYS.trainingState, {}),
        loadJSON<UpgradeProposal[]>(STORAGE_KEYS.proposals, []),
        loadJSON<StudioSnapshot[]>(STORAGE_KEYS.snapshots, []),
      ]);
      setProjects(p);
      setMemories(m ?? SEED_MEMORIES);
      setKnowledge(k ?? SEED_KNOWLEDGE);
      setSettings({ ...DEFAULT_SETTINGS, ...s });
      const seeded: Record<string, boolean> = { ...t };
      for (const mod of TRAINING_MODULES) {
        for (const lesson of mod.lessons) {
          const key = `${mod.id}:${lesson.id}`;
          if (seeded[key] === undefined) seeded[key] = lesson.trained;
        }
      }
      setTrainedLessons(seeded);
      setProposals(pr);
      setSnapshots(sn);
      setReady(true);
    })();
  }, []);

  const persistProjects = useCallback(async (next: Project[]) => {
    projectsRef.current = next;
    setProjects(next);
    await saveJSON(STORAGE_KEYS.projects, next);
  }, []);

  const persistMemories = useCallback(async (next: MemoryEntry[]) => {
    memoriesRef.current = next;
    setMemories(next);
    await saveJSON(STORAGE_KEYS.memories, next);
  }, []);

  const persistKnowledge = useCallback(async (next: KnowledgeEntry[]) => {
    knowledgeRef.current = next;
    setKnowledge(next);
    await saveJSON(STORAGE_KEYS.knowledge, next);
  }, []);

  const persistSettings = useCallback(async (next: AppSettings) => {
    settingsRef.current = next;
    setSettings(next);
    await saveJSON(STORAGE_KEYS.settings, next);
  }, []);

  const persistTraining = useCallback(
    async (next: Record<string, boolean>) => {
      trainedRef.current = next;
      setTrainedLessons(next);
      await saveJSON(STORAGE_KEYS.trainingState, next);
    },
    [],
  );

  const persistProposals = useCallback(async (next: UpgradeProposal[]) => {
    setProposals(next);
    await saveJSON(STORAGE_KEYS.proposals, next);
  }, []);

  const persistSnapshots = useCallback(async (next: StudioSnapshot[]) => {
    setSnapshots(next);
    await saveJSON(STORAGE_KEYS.snapshots, next);
  }, []);

  const updateProject = useCallback((updated: Project) => {
    const next = projectsRef.current.map((p) =>
      p.id === updated.id ? updated : p,
    );
    projectsRef.current = next;
    setProjects(next);
    saveJSON(STORAGE_KEYS.projects, next);
  }, []);

  const buildPrompt = (
    role: AgentStep["role"],
    desc: string,
    platform: Platform,
  ): { system: string; user: string } => {
    const memoryHints = memoriesRef.current
      .filter((m) => m.autoInclude)
      .slice(0, 6)
      .map((m) => `- ${m.title}: ${m.body.slice(0, 120)}`)
      .join("\n");

    const base = `You are the ${role.toUpperCase()} agent inside Agent Studio, a 5-stage AI build pipeline (Architect → Builder → UI Designer → QA → Packager). Target platform: ${platform.toUpperCase()}. Be concise, structured, and produce real, useful technical output. Use markdown headings and short bullet lists. Never refuse — always produce something useful.${memoryHints ? `\n\nRelevant memories:\n${memoryHints}` : ""}`;

    const userByRole: Record<AgentStep["role"], string> = {
      architect: `Plan the architecture for this app idea: "${desc}".\nReturn:\n- Module / package structure\n- Key entities & data models\n- State management approach\n- Navigation flow\n- 3-5 architectural decisions and why.`,
      builder: `Write the core source skeleton for: "${desc}". Provide 2-3 representative source files (with file paths) implementing the architecture. Keep each file short (under 40 lines). Use ${platform === "android" ? "Kotlin + Jetpack Compose" : platform === "web" ? "React + TypeScript + Tailwind" : "Flutter + Riverpod"}.`,
      designer: `Design the UI for: "${desc}". Provide:\n- Color palette (5 hex values with names)\n- Typography scale\n- 3-5 key screens described in 1 line each\n- 1 representative ${platform === "android" ? "@Composable" : platform === "web" ? "JSX" : "Widget"} component (under 30 lines).`,
      qa: `Review the codebase for: "${desc}". List:\n- 5 likely bug categories to check\n- Null safety / error handling fixes\n- Suggested unit tests with names\n- 1 priority issue and its proposed fix.`,
      packager: `Finalize the build for: "${desc}".\nReturn:\n- Build manifest (name, version, package id, target SDK, permissions)\n- Output artifact summary\n- Post-build checklist\n- "READY TO SHIP" verdict.`,
    };

    return { system: base, user: userByRole[role] };
  };

  const runAgent = async (
    role: AgentStep["role"],
    description: string,
    platform: Platform,
    signal?: AbortSignal,
  ): Promise<string> => {
    const { system, user } = buildPrompt(role, description, platform);
    return pollinate(
      [
        { role: "system", content: system },
        { role: "user", content: user },
      ],
      { signal },
    );
  };

  const orchestrate = useCallback(
    async (project: Project) => {
      setActiveBuildId(project.id);
      let working = { ...project };

      for (let i = 0; i < working.steps.length; i++) {
        const step = working.steps[i];
        if (!step) continue;
        if (step.status === "done") continue; // already completed (resume support)

        working = {
          ...working,
          status: "building",
          steps: working.steps.map((s, idx) =>
            idx === i
              ? { ...s, status: "running", startedAt: Date.now() }
              : s,
          ),
          updatedAt: Date.now(),
        };
        updateProject(working);

        try {
          const output = await runAgent(
            step.role,
            working.description,
            working.platform,
          );
          working = {
            ...working,
            steps: working.steps.map((s, idx) =>
              idx === i
                ? {
                    ...s,
                    status: "done",
                    output,
                    finishedAt: Date.now(),
                  }
                : s,
            ),
            updatedAt: Date.now(),
          };
          updateProject(working);
        } catch (err) {
          const message =
            err instanceof Error ? err.message : "Unknown agent error";
          working = {
            ...working,
            status: "failed",
            steps: working.steps.map((s, idx) =>
              idx === i
                ? {
                    ...s,
                    status: "error",
                    output: `Agent failed: ${message}`,
                    finishedAt: Date.now(),
                  }
                : s,
            ),
            updatedAt: Date.now(),
          };
          updateProject(working);
          setActiveBuildId(null);
          return;
        }
      }

      working = {
        ...working,
        status: "ready",
        manifest: `${working.name.toLowerCase().replace(/\s+/g, "-")}-1.0.0.${working.platform === "android" ? "apk" : working.platform === "web" ? "zip" : "ipa"}`,
        updatedAt: Date.now(),
      };
      updateProject(working);
      setActiveBuildId(null);

      if (settingsRef.current.selfUpgradingAgents) {
        const memEntry: MemoryEntry = {
          id: newId("mem-"),
          type: "solution",
          title: `Build pattern: ${working.name}`,
          body: `Successfully built "${working.description}" on ${working.platform}. Pipeline completed in ${working.steps.length} stages.`,
          tags: ["build", working.platform, "auto-learned"],
          autoInclude: true,
          createdAt: Date.now(),
        };
        const next = [memEntry, ...memoriesRef.current];
        memoriesRef.current = next;
        setMemories(next);
        await saveJSON(STORAGE_KEYS.memories, next);
      }

      if (settingsRef.current.autoDownloadOnComplete) {
        try {
          await exportBundle(buildProjectBundle(working));
        } catch {
          // user can manually export from the build screen
        }
      }
    },
    [updateProject],
  );

  const startBuild = useCallback<Ctx["startBuild"]>(
    async ({ description, platform, name }) => {
      const id = newId("proj-");
      const projectName =
        name?.trim() ||
        description
          .split(/\s+/)
          .slice(0, 4)
          .join(" ")
          .replace(/[^a-zA-Z0-9 ]/g, "")
          .trim() ||
        "New Build";

      const steps: AgentStep[] = PIPELINE.map((p) => ({
        role: p.role,
        name: p.name,
        status: "queued",
        output: "",
      }));

      const proj: Project = {
        id,
        name: projectName,
        description,
        platform,
        status: "building",
        steps,
        createdAt: Date.now(),
        updatedAt: Date.now(),
      };

      const next = [proj, ...projectsRef.current];
      await persistProjects(next);
      orchestrate(proj);
      return id;
    },
    [orchestrate, persistProjects],
  );

  const retryBuild = useCallback<Ctx["retryBuild"]>(
    async (id) => {
      const proj = projectsRef.current.find((p) => p.id === id);
      if (!proj) return;
      const reset: Project = {
        ...proj,
        status: "building",
        steps: proj.steps.map((s) => ({
          ...s,
          status: "queued",
          output: "",
          startedAt: undefined,
          finishedAt: undefined,
        })),
        updatedAt: Date.now(),
      };
      await persistProjects(
        projectsRef.current.map((p) => (p.id === id ? reset : p)),
      );
      orchestrate(reset);
    },
    [orchestrate, persistProjects],
  );

  const resumeBuild = useCallback<Ctx["resumeBuild"]>(
    async (id) => {
      const proj = projectsRef.current.find((p) => p.id === id);
      if (!proj) return;
      // Reset any stuck "running" step back to queued so it picks up where it left off
      const fixed: Project = {
        ...proj,
        status: "building",
        steps: proj.steps.map((s) =>
          s.status === "running"
            ? { ...s, status: "queued", startedAt: undefined }
            : s,
        ),
        updatedAt: Date.now(),
      };
      await persistProjects(
        projectsRef.current.map((p) => (p.id === id ? fixed : p)),
      );
      orchestrate(fixed);
    },
    [orchestrate, persistProjects],
  );

  const deleteProject = useCallback<Ctx["deleteProject"]>(
    async (id) => {
      await persistProjects(projectsRef.current.filter((p) => p.id !== id));
    },
    [persistProjects],
  );

  const getProject = useCallback(
    (id: string) => projects.find((p) => p.id === id),
    [projects],
  );

  const exportProject = useCallback<Ctx["exportProject"]>(async (id) => {
    const proj = projectsRef.current.find((p) => p.id === id);
    if (!proj) return { ok: false, message: "Project not found." };
    return exportBundle(buildProjectBundle(proj));
  }, []);

  const exportSourceCode = useCallback<Ctx["exportSourceCode"]>(async () => {
    const bundle = await buildSourceCodeBundle();
    return exportBundle(bundle);
  }, []);

  const pushToGithub = useCallback<Ctx["pushToGithub"]>(
    async (id, onProgress) => {
      const proj = projectsRef.current.find((p) => p.id === id);
      if (!proj) return { ok: false, message: "Project not found." };
      return pushProjectToRepo({
        project: proj,
        repoSlug: settingsRef.current.githubRepo,
        token: settingsRef.current.githubToken,
        onProgress,
      });
    },
    [],
  );

  const addMemory: Ctx["addMemory"] = async (m) => {
    const entry: MemoryEntry = {
      ...m,
      id: newId("mem-"),
      createdAt: Date.now(),
    };
    await persistMemories([entry, ...memoriesRef.current]);
  };

  const removeMemory: Ctx["removeMemory"] = async (id) => {
    await persistMemories(memoriesRef.current.filter((m) => m.id !== id));
  };

  const addKnowledge: Ctx["addKnowledge"] = async (k) => {
    const entry: KnowledgeEntry = {
      ...k,
      id: newId("kn-"),
      createdAt: Date.now(),
    };
    await persistKnowledge([entry, ...knowledgeRef.current]);
  };

  const removeKnowledge: Ctx["removeKnowledge"] = async (id) => {
    await persistKnowledge(knowledgeRef.current.filter((m) => m.id !== id));
  };

  const updateSettings: Ctx["updateSettings"] = async (patch) => {
    await persistSettings({ ...settingsRef.current, ...patch });
  };

  const trainLesson: Ctx["trainLesson"] = async (moduleId, lessonId) => {
    const key = `${moduleId}:${lessonId}`;
    const next = { ...trainedRef.current, [key]: true };
    await persistTraining(next);

    const mod = TRAINING_MODULES.find((m) => m.id === moduleId);
    const lesson = mod?.lessons.find((l) => l.id === lessonId);
    if (mod && lesson) {
      const entry: MemoryEntry = {
        id: newId("mem-"),
        type: "doc",
        title: `${lesson.title} — ${mod.agent} Training`,
        body: `Trained: ${lesson.title} — ${mod.agent} agent`,
        tags: ["training", mod.agent.toLowerCase(), "learned"],
        autoInclude: true,
        createdAt: Date.now(),
      };
      await persistMemories([entry, ...memoriesRef.current]);
    }
  };

  const trainModule: Ctx["trainModule"] = async (moduleId) => {
    const mod = TRAINING_MODULES.find((m) => m.id === moduleId);
    if (!mod) return;
    const next = { ...trainedRef.current };
    const newMems: MemoryEntry[] = [];
    for (const lesson of mod.lessons) {
      const key = `${moduleId}:${lesson.id}`;
      if (!next[key]) {
        next[key] = true;
        newMems.push({
          id: newId("mem-"),
          type: "doc",
          title: `${lesson.title} — ${mod.agent} Training`,
          body: `Trained: ${lesson.title} — ${mod.agent} agent`,
          tags: ["training", mod.agent.toLowerCase(), "learned"],
          autoInclude: true,
          createdAt: Date.now(),
        });
      }
    }
    await persistTraining(next);
    if (newMems.length) {
      await persistMemories([...newMems, ...memoriesRef.current]);
    }
  };

  const resetTraining: Ctx["resetTraining"] = async () => {
    await persistTraining({});
  };

  const takeSnapshot = useCallback(
    async (label: string): Promise<StudioSnapshot> => {
      const snap: StudioSnapshot = {
        id: newId("snap-"),
        label,
        createdAt: Date.now(),
        settings: settingsRef.current,
        memories: memoriesRef.current,
        knowledge: knowledgeRef.current,
        trainedLessons: trainedRef.current,
      };
      const next = [snap, ...snapshots].slice(0, MAX_SNAPSHOTS);
      await persistSnapshots(next);
      return snap;
    },
    [persistSnapshots, snapshots],
  );

  const analyzeForUpgrades: Ctx["analyzeForUpgrades"] = useCallback(async () => {
    const summary = `Stack snapshot:
- Pollinations primary (free, no key)
- Groq key set: ${settingsRef.current.groqKey ? "yes" : "no"}
- Custom OpenAI key set: ${settingsRef.current.customKey ? "yes" : "no"}
- Memories: ${memoriesRef.current.length}
- Knowledge entries: ${knowledgeRef.current.length}
- Projects built: ${projectsRef.current.length}
- Build prefs: liveCodeFeed=${settingsRef.current.liveCodeFeed}, selfUpgrading=${settingsRef.current.selfUpgradingAgents}, requireApproval=${settingsRef.current.requireApprovalForUpgrades}, previewChanges=${settingsRef.current.previewChangesBeforeExecuting}, autoRollback=${settingsRef.current.autoRollbackOnFailure}
- Failing builds: ${projectsRef.current.filter((p) => p.status === "failed").length}`;

    let analysisText = "";
    try {
      analysisText = await pollinate([
        {
          role: "system",
          content:
            "You are the self-upgrade auditor for Agent Studio. Identify 2-4 concrete safety/quality improvements the studio should make to itself. Return STRICT JSON: {\"summary\":\"…\",\"proposals\":[{\"title\":\"…\",\"rationale\":\"…\",\"settings\":{<partial AppSettings keys>},\"memory\":{\"title\":\"…\",\"body\":\"…\",\"tags\":[\"…\"]}}]}.\nValid AppSettings boolean keys: autoDownloadOnComplete, buildNotifications, liveCodeFeed, selfUpgradingAgents, requireApprovalForUpgrades, previewChangesBeforeExecuting, autoRollbackOnFailure.\nNo prose outside the JSON.",
        },
        { role: "user", content: summary },
      ]);
    } catch {
      analysisText = "";
    }

    const parsed = parseProposals(analysisText);
    const fallback = parsed.length === 0 ? buildHeuristicProposals(settingsRef.current) : parsed;

    const dated: UpgradeProposal[] = fallback.map((p) => ({
      ...p,
      id: newId("up-"),
      createdAt: Date.now(),
    }));
    await persistProposals([...dated, ...proposals.filter((p) => p.applied)]);
    return dated;
  }, [persistProposals, proposals]);

  const applyUpgrade: Ctx["applyUpgrade"] = useCallback(
    async (proposalId) => {
      const proposal =
        proposals.find((p) => p.id === proposalId) ?? null;
      if (!proposal) return { ok: false, message: "Proposal not found." };

      const snap = await takeSnapshot(`Before: ${proposal.summary}`);

      try {
        if (proposal.changes.settingsPatch) {
          const nextSettings = {
            ...settingsRef.current,
            ...proposal.changes.settingsPatch,
          };
          await persistSettings(nextSettings);
        }
        if (proposal.changes.addMemories?.length) {
          const newMems: MemoryEntry[] = proposal.changes.addMemories.map(
            (m) => ({
              id: newId("mem-"),
              type: "solution",
              title: m.title,
              body: m.body,
              tags: m.tags,
              autoInclude: true,
              createdAt: Date.now(),
            }),
          );
          await persistMemories([...newMems, ...memoriesRef.current]);
        }

        const nextProposals = proposals.map((p) =>
          p.id === proposalId
            ? {
                ...p,
                applied: true,
                appliedAt: Date.now(),
                snapshotId: snap.id,
              }
            : p,
        );
        await persistProposals(nextProposals);

        return {
          ok: true,
          message:
            "Upgrade applied. A snapshot was saved so you can roll back from Settings → Infrastructure.",
        };
      } catch (err) {
        // Auto rollback on failure
        if (settingsRef.current.autoRollbackOnFailure) {
          await persistSettings(snap.settings);
          await persistMemories(snap.memories);
        }
        return {
          ok: false,
          message: err instanceof Error ? err.message : "Apply failed",
        };
      }
    },
    [persistMemories, persistProposals, persistSettings, proposals, takeSnapshot],
  );

  const rollbackUpgrade: Ctx["rollbackUpgrade"] = useCallback(
    async (snapshotId) => {
      const snap = snapshots.find((s) => s.id === snapshotId);
      if (!snap) return { ok: false, message: "Snapshot not found." };
      await persistSettings(snap.settings);
      await persistMemories(snap.memories);
      await persistKnowledge(snap.knowledge);
      await persistTraining(snap.trainedLessons);
      const nextProposals = proposals.map((p) =>
        p.snapshotId === snapshotId
          ? { ...p, applied: false, rolledBackAt: Date.now() }
          : p,
      );
      await persistProposals(nextProposals);
      return { ok: true, message: "Restored from snapshot." };
    },
    [
      persistKnowledge,
      persistMemories,
      persistProposals,
      persistSettings,
      persistTraining,
      proposals,
      snapshots,
    ],
  );

  const dismissProposal: Ctx["dismissProposal"] = useCallback(
    async (proposalId) => {
      await persistProposals(proposals.filter((p) => p.id !== proposalId));
    },
    [persistProposals, proposals],
  );

  const value = useMemo<Ctx>(
    () => ({
      ready,
      projects,
      memories,
      knowledge,
      settings,
      trainedLessons,
      proposals,
      snapshots,
      activeBuildId,
      startBuild,
      retryBuild,
      resumeBuild,
      deleteProject,
      getProject,
      exportProject,
      exportSourceCode,
      pushToGithub,
      addMemory,
      removeMemory,
      addKnowledge,
      removeKnowledge,
      updateSettings,
      trainLesson,
      trainModule,
      resetTraining,
      analyzeForUpgrades,
      applyUpgrade,
      rollbackUpgrade,
      dismissProposal,
    }),
    [
      ready,
      projects,
      memories,
      knowledge,
      settings,
      trainedLessons,
      proposals,
      snapshots,
      activeBuildId,
      startBuild,
      retryBuild,
      resumeBuild,
      deleteProject,
      getProject,
      exportProject,
      exportSourceCode,
      pushToGithub,
      analyzeForUpgrades,
      applyUpgrade,
      rollbackUpgrade,
      dismissProposal,
    ],
  );

  return (
    <StudioContext.Provider value={value}>{children}</StudioContext.Provider>
  );
}

export function useStudio() {
  const ctx = useContext(StudioContext);
  if (!ctx) throw new Error("useStudio must be used inside StudioProvider");
  return ctx;
}

const VALID_BOOL_KEYS: (keyof AppSettings)[] = [
  "autoDownloadOnComplete",
  "buildNotifications",
  "liveCodeFeed",
  "selfUpgradingAgents",
  "requireApprovalForUpgrades",
  "previewChangesBeforeExecuting",
  "autoRollbackOnFailure",
];

interface RawProposal {
  rationale: string;
  summary: string;
  changes: UpgradeProposal["changes"];
}

function parseProposals(text: string): RawProposal[] {
  if (!text) return [];
  const match = text.match(/\{[\s\S]*\}/);
  if (!match) return [];
  try {
    const parsed = JSON.parse(match[0]) as {
      proposals?: {
        title?: string;
        rationale?: string;
        settings?: Record<string, unknown>;
        memory?: { title?: string; body?: string; tags?: unknown };
      }[];
    };
    if (!Array.isArray(parsed.proposals)) return [];
    return parsed.proposals.slice(0, 4).map((p) => {
      const settingsPatch: Partial<AppSettings> = {};
      if (p.settings && typeof p.settings === "object") {
        for (const [k, v] of Object.entries(p.settings)) {
          if (VALID_BOOL_KEYS.includes(k as keyof AppSettings) && typeof v === "boolean") {
            (settingsPatch as Record<string, boolean>)[k] = v;
          }
        }
      }
      const addMemories: { title: string; body: string; tags: string[] }[] = [];
      if (p.memory?.title && p.memory?.body) {
        const rawTags = Array.isArray(p.memory.tags) ? p.memory.tags : [];
        const tags = rawTags
          .filter((t): t is string => typeof t === "string")
          .slice(0, 6);
        addMemories.push({
          title: String(p.memory.title).slice(0, 80),
          body: String(p.memory.body).slice(0, 400),
          tags: tags.length ? tags : ["self-upgrade"],
        });
      }
      return {
        summary: String(p.title ?? "Upgrade").slice(0, 100),
        rationale: String(p.rationale ?? "").slice(0, 400),
        changes: { settingsPatch, addMemories },
      };
    });
  } catch {
    return [];
  }
}

function buildHeuristicProposals(s: AppSettings): RawProposal[] {
  const out: RawProposal[] = [];
  if (!s.requireApprovalForUpgrades) {
    out.push({
      summary: "Require approval before applying agent upgrades",
      rationale:
        "Self-upgrading agents should ask for explicit approval. This prevents silent regressions.",
      changes: {
        settingsPatch: { requireApprovalForUpgrades: true },
        addMemories: [
          {
            title: "Safety: approval-gated upgrades",
            body: "Agents must request approval before mutating studio state.",
            tags: ["safety", "self-upgrade"],
          },
        ],
      },
    });
  }
  if (!s.autoRollbackOnFailure) {
    out.push({
      summary: "Enable automatic rollback on failure",
      rationale:
        "If an upgrade or build fails mid-flight, revert state automatically.",
      changes: {
        settingsPatch: { autoRollbackOnFailure: true },
        addMemories: [
          {
            title: "Safety: auto-rollback",
            body: "Failed apply paths revert to the last snapshot.",
            tags: ["safety", "rollback"],
          },
        ],
      },
    });
  }
  if (!s.previewChangesBeforeExecuting) {
    out.push({
      summary: "Preview changes before executing",
      rationale: "Show a diff so the user can approve or reject every mutation.",
      changes: {
        settingsPatch: { previewChangesBeforeExecuting: true },
      },
    });
  }
  if (out.length === 0) {
    out.push({
      summary: "Capture a fresh memory bank snapshot",
      rationale:
        "All safety knobs already on — record a checkpoint of the current studio state.",
      changes: {
        addMemories: [
          {
            title: "Self-upgrade audit baseline",
            body: "All safety knobs verified on. Studio configuration treated as known-good baseline.",
            tags: ["self-upgrade", "baseline"],
          },
        ],
      },
    });
  }
  return out;
}

import { useColorScheme } from "react-native";

import colors from "@/constants/colors";

/**
 * Returns the design tokens for the current color scheme.
 *
 * The returned object contains all color tokens for the active palette
 * plus scheme-independent values like `radius`.
 *
 * Falls back to the light palette when no dark key is defined in
 * constants/colors.ts (the scaffold ships light-only by default).
 * When a sibling web artifact's dark tokens are synced into a `dark`
 * key, this hook will automatically switch palettes based on the
 * device's appearance setting.
 */
export function useColors() {
  const scheme = useColorScheme();
  const palette =
    scheme === "dark" && "dark" in colors
      ? (colors as Record<string, typeof colors.light>).dark
      : colors.light;
  return { ...palette, radius: colors.radius };
}

import { Platform, Share } from "react-native";

import type { Project } from "./types";

// Generated at workspace start (`pnpm predev`) by scripts/build-source-bundle.mjs
// We use a static require so Metro inlines it into the JS bundle and it works
// in both web and native runtimes without an HTTP request.
// eslint-disable-next-line @typescript-eslint/no-require-imports, @typescript-eslint/no-explicit-any
const SOURCE_BUNDLE: SourceBundle = require("../assets/source-bundle.json") as any;

interface SourceBundle {
  app: string;
  generatedAt: string;
  fileCount: number;
  totalBytes: number;
  extractInstructions: string;
  files: { path: string; bytes: number; content: string }[];
}

export interface Bundle {
  filename: string;
  content: string;
  mime: string;
}

function safeName(s: string): string {
  return s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 48);
}

export function buildProjectBundle(project: Project): Bundle {
  const ext =
    project.platform === "android"
      ? "android-bundle.txt"
      : project.platform === "web"
        ? "web-bundle.txt"
        : "flutter-bundle.txt";
  const filename = `${safeName(project.name) || "project"}-${project.id.slice(-6)}.${ext}`;
  const lines: string[] = [];
  lines.push(`# Agent Studio Build`);
  lines.push(``);
  lines.push(`- Project: ${project.name}`);
  lines.push(`- Description: ${project.description}`);
  lines.push(`- Platform: ${project.platform}`);
  lines.push(`- Status: ${project.status}`);
  lines.push(`- Manifest: ${project.manifest ?? "(pending)"}`);
  lines.push(`- Created: ${new Date(project.createdAt).toISOString()}`);
  lines.push(`- Updated: ${new Date(project.updatedAt).toISOString()}`);
  lines.push(``);
  lines.push(`## Pipeline`);
  lines.push(``);
  for (const step of project.steps) {
    lines.push(`### ${step.name} (${step.role}) — ${step.status.toUpperCase()}`);
    lines.push(``);
    lines.push(step.output?.trim() || "_(no output yet)_");
    lines.push(``);
  }
  return { filename, content: lines.join("\n"), mime: "text/markdown" };
}

/**
 * Returns the full source code of the Agent Studio app as a single
 * downloadable JSON file. Contents come from the build-time bundle generated
 * by `scripts/build-source-bundle.mjs`. The user can extract the archive on
 * disk with the one-liner included in `extractInstructions`.
 */
export async function buildSourceCodeBundle(): Promise<Bundle> {
  const ts = new Date().toISOString().replace(/[:.]/g, "-");
  const filename = `agent-studio-source-${ts}.json`;
  const content = JSON.stringify(SOURCE_BUNDLE);
  return { filename, content, mime: "application/json" };
}

export function getSourceBundleSummary(): {
  fileCount: number;
  totalBytes: number;
  generatedAt: string;
} {
  return {
    fileCount: SOURCE_BUNDLE.fileCount,
    totalBytes: SOURCE_BUNDLE.totalBytes,
    generatedAt: SOURCE_BUNDLE.generatedAt,
  };
}

export async function exportBundle(bundle: Bundle): Promise<{
  ok: boolean;
  message: string;
}> {
  if (Platform.OS === "web") {
    try {
      const blob = new Blob([bundle.content], { type: bundle.mime });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = bundle.filename;
      a.style.display = "none";
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(() => URL.revokeObjectURL(url), 10_000);
      return { ok: true, message: `Saved ${bundle.filename} to Downloads.` };
    } catch (err) {
      return {
        ok: false,
        message: err instanceof Error ? err.message : "Browser download failed",
      };
    }
  }

  try {
    await Share.share({
      title: bundle.filename,
      message: bundle.content,
    });
    return { ok: true, message: "Share sheet opened." };
  } catch (err) {
    return {
      ok: false,
      message: err instanceof Error ? err.message : "Share failed",
    };
  }
}

import type { Project, AgentStep } from "./types";

const API = "https://api.github.com";

// ─── Encoding ───────────────────────────────────────────────────────────────

function utf8ToBase64(input: string): string {
  if (typeof globalThis.btoa === "function") {
    const bytes = new TextEncoder().encode(input);
    let bin = "";
    for (let i = 0; i < bytes.length; i++) {
      bin += String.fromCharCode(bytes[i] as number);
    }
    return globalThis.btoa(bin);
  }
  type BufLike = { from: (s: string, e: string) => { toString: (e: string) => string } };
  const G = globalThis as unknown as { Buffer?: BufLike };
  if (G.Buffer) return G.Buffer.from(input, "utf-8").toString("base64");
  throw new Error("No base64 encoder found on this runtime.");
}

// ─── Slug / repo parsing ─────────────────────────────────────────────────────

export function slugify(s: string): string {
  return (
    s
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 48) || "project"
  );
}

export function parseRepoSlug(raw: string): { owner: string; repo: string } | null {
  const cleaned = raw.trim().replace(/^https?:\/\/(www\.)?github\.com\//, "");
  const m = cleaned.match(/^([\w.-]+)\/([\w.-]+?)(\.git)?$/);
  if (!m) return null;
  return { owner: m[1] as string, repo: m[2] as string };
}

// ─── GitHub API helpers ──────────────────────────────────────────────────────

interface GhAuth { token: string }

async function gh(path: string, init: RequestInit & { auth: GhAuth }): Promise<Response> {
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${init.auth.token}`,
  };
  if (init.body) headers["Content-Type"] = "application/json";
  return fetch(`${API}${path}`, { ...init, headers });
}

export async function verifyRepoAccess(
  repo: { owner: string; repo: string },
  token: string,
): Promise<{ ok: boolean; defaultBranch?: string; message: string }> {
  try {
    const res = await gh(`/repos/${repo.owner}/${repo.repo}`, { method: "GET", auth: { token } });
    if (res.status === 404) return { ok: false, message: "Repo not found or token has no access." };
    if (res.status === 401) return { ok: false, message: "Token rejected (401). Check the token scope." };
    if (!res.ok) return { ok: false, message: `GitHub error ${res.status}` };
    const j = (await res.json()) as { default_branch?: string };
    return { ok: true, defaultBranch: j.default_branch ?? "main", message: `Connected — branch: ${j.default_branch ?? "main"}` };
  } catch (e) {
    return { ok: false, message: e instanceof Error ? e.message : "Network error" };
  }
}

async function getFileSha(
  repo: { owner: string; repo: string },
  filePath: string,
  branch: string,
  token: string,
): Promise<string | null> {
  const res = await gh(
    `/repos/${repo.owner}/${repo.repo}/contents/${encodeURI(filePath)}?ref=${encodeURIComponent(branch)}`,
    { method: "GET", auth: { token } },
  );
  if (res.status === 404) return null;
  if (!res.ok) throw new Error(`GitHub ${res.status}: ${(await res.text().catch(() => "")).slice(0, 140)}`);
  const j = (await res.json()) as { sha?: string };
  return j.sha ?? null;
}

async function putFile(
  repo: { owner: string; repo: string },
  filePath: string,
  content: string,
  message: string,
  branch: string,
  token: string,
): Promise<void> {
  const sha = await getFileSha(repo, filePath, branch, token);
  const body: Record<string, unknown> = { message, content: utf8ToBase64(content), branch };
  if (sha) body.sha = sha;
  const res = await gh(
    `/repos/${repo.owner}/${repo.repo}/contents/${encodeURI(filePath)}`,
    { method: "PUT", auth: { token }, body: JSON.stringify(body) },
  );
  if (!res.ok) {
    throw new Error(`PUT ${filePath} → ${res.status}: ${(await res.text().catch(() => "")).slice(0, 140)}`);
  }
}

// ─── Code extraction ─────────────────────────────────────────────────────────

const CODE_FENCE_RE =
  /```(?:typescript|tsx|jsx|ts|js|react-native|react|javascript)?\n([\s\S]*?)```/g;

interface ExtractedCode {
  main: string;        // App.tsx content (may be synthesised)
  extras: { name: string; content: string }[];  // additional component files
}

function extractCode(steps: AgentStep[]): ExtractedCode {
  // Prefer UI Designer output, then Builder, then Architect
  const ordered = ["ui_designer", "builder", "architect", "qa", "packager"] as const;
  const byRole: Record<string, AgentStep> = {};
  for (const s of steps) byRole[s.role] = s;

  for (const role of ordered) {
    const step = byRole[role];
    if (!step?.output) continue;

    const blocks: string[] = [];
    let m: RegExpExecArray | null;
    CODE_FENCE_RE.lastIndex = 0;
    while ((m = CODE_FENCE_RE.exec(step.output)) !== null) {
      const block = (m[1] ?? "").trim();
      if (block.length > 120) blocks.push(block);
    }

    // Look for a block that looks like an Expo/RN App component
    const mainBlock = blocks.find(
      (b) =>
        b.includes("export default") &&
        (b.includes("react-native") || b.includes("View") || b.includes("Text")),
    );
    if (mainBlock) {
      const extras = blocks
        .filter((b) => b !== mainBlock && b.includes("export"))
        .slice(0, 4)
        .map((b, i) => ({ name: `components/Generated${i + 1}.tsx`, content: b }));
      return { main: mainBlock, extras };
    }

    // Fallback: take the longest block that has imports
    const withImports = blocks.filter((b) => b.includes("import ")).sort((a, b) => b.length - a.length);
    if (withImports[0] && withImports[0].length > 200) {
      return { main: withImports[0], extras: [] };
    }
  }

  // Nothing found — generate a smart placeholder
  return { main: "", extras: [] };
}

// ─── Scaffold generators ──────────────────────────────────────────────────────

function makeAppTsx(project: Project, extractedMain: string): string {
  if (extractedMain.trim().length > 0) {
    // Ensure we have the right imports at the top
    const hasImport = extractedMain.includes("import React") || extractedMain.includes("from 'react'");
    const prefix = hasImport ? "" : "import React from 'react';\n";
    return `${prefix}// Generated by Agent Studio — ${project.name}\n// Modify freely.\n\n${extractedMain}\n`;
  }

  // Smart placeholder based on project description
  const title = project.name;
  const desc = project.description.replace(/'/g, "\\'").slice(0, 80);
  const steps = project.steps
    .filter((s) => s.status === "done")
    .map((s) => `  "${s.name}: ${s.status}"`)
    .join(",\n");

  return `import React from 'react';
