// ─── Push result ──────────────────────────────────────────────────────────────

export interface PushResult {
  ok: boolean;
  message: string;
  url?: string;
  filesPushed?: number;
}

// ─── Main push ────────────────────────────────────────────────────────────────

export async function pushProjectToRepo(input: {
  project: Project;
  repoSlug: string;
  token: string;
  onProgress?: (msg: string) => void;
}): Promise<PushResult> {
  const repo = parseRepoSlug(input.repoSlug);
  if (!repo) return { ok: false, message: "Repo must be in the form owner/name." };
  if (!input.token.trim()) return { ok: false, message: "Add a GitHub token in AI Settings first." };

  const progress = input.onProgress ?? (() => void 0);

  progress("Checking repo access…");
  const verify = await verifyRepoAccess(repo, input.token);
  if (!verify.ok) return { ok: false, message: verify.message };
  const branch = verify.defaultBranch ?? "main";

  const slug = slugify(input.project.name);
  const dir = `agent-studio/${slug}`;

  // ── Extract code from pipeline ───────────────────────────────────────────
  progress("Extracting code from pipeline…");
  const { main: mainCode, extras } = extractCode(input.project.steps);

  // ── Build file list ──────────────────────────────────────────────────────
  const files: { path: string; content: string; label: string }[] = [
    {
      path: `${dir}/App.tsx`,
      content: makeAppTsx(input.project, mainCode),
      label: "App.tsx",
    },
    {
      path: `${dir}/app.json`,
      content: makeAppJson(input.project.name, slug, input.project.platform),
      label: "app.json",
    },
    {
      path: `${dir}/package.json`,
      content: makePackageJson(slug, input.project.platform),
      label: "package.json",
    },
    {
      path: `${dir}/tsconfig.json`,
      content: TSCONFIG,
      label: "tsconfig.json",
    },
    {
      path: `${dir}/babel.config.js`,
      content: BABEL_CONFIG,
      label: "babel.config.js",
    },
    {
      path: `${dir}/.gitignore`,
      content: GITIGNORE,
      label: ".gitignore",
    },
    {
      path: `${dir}/README.md`,
      content: makeReadme(input.project, slug, repo.owner, repo.repo, branch),
      label: "README.md",
    },
  ];

  // Extra extracted component files
  for (const extra of extras) {
    files.push({
      path: `${dir}/${extra.name}`,
      content: extra.content,
      label: extra.name,
    });
  }

  // Agent docs
  for (const step of input.project.steps) {
    const docNum: Record<string, string> = { architect: "01", builder: "02", ui_designer: "03", qa: "04", packager: "05" };
    const num = docNum[step.role] ?? "00";
    const body = step.output?.trim() || `_(${step.name} produced no output)_`;
    files.push({
      path: `${dir}/docs/${num}-${step.role}.md`,
      content: `# ${step.name}\n\nRole: \`${step.role}\`  ·  Status: \`${step.status}\`\n\n---\n\n${body}\n`,
      label: `docs/${step.role}.md`,
    });
  }

  // ── Push files one by one ────────────────────────────────────────────────
  let pushed = 0;
  try {
    for (const file of files) {
      progress(`Pushing ${file.label} (${pushed + 1}/${files.length})…`);
      await putFile(
        repo,
        file.path,
        file.content,
        `Agent Studio: ${input.project.name} → ${file.label}`,
        branch,
        input.token,
      );
      pushed += 1;
    }

    return {
      ok: true,
      filesPushed: pushed,
      url: `https://github.com/${repo.owner}/${repo.repo}/tree/${branch}/${dir}`,
      message: `Pushed ${pushed} files (${extras.length > 0 ? "with extracted code" : mainCode ? "with extracted code" : "with starter placeholder"}).`,
    };
  } catch (e) {
    return {
      ok: false,
      message: e instanceof Error ? e.message : "Push failed",
      filesPushed: pushed,
    };
  }
}

export function newId(prefix = ""): string {
  return (
    prefix + Date.now().toString(36) + Math.random().toString(36).slice(2, 9)
  );
}

// Pollinations AI client — free, no key required.
// Uses the OpenAI-compatible endpoint at https://text.pollinations.ai/openai
// Adds a transparent offline cache so previously seen prompts return their last
// successful response when the device is offline or the API errors.

import AsyncStorage from "@react-native-async-storage/async-storage";

const TEXT_ENDPOINT = "https://text.pollinations.ai/openai";
const PING_ENDPOINT = "https://text.pollinations.ai/models";
const CACHE_PREFIX = "agent-studio:cache:pollinate:";
const CACHE_INDEX_KEY = "agent-studio:cache:pollinate-index";
const MAX_CACHE_ENTRIES = 80;

export interface ChatMessage {
  role: "system" | "user" | "assistant";
  content: string;
}

export interface PollinationsOptions {
  model?: string;
  temperature?: number;
  signal?: AbortSignal;
  /** Skip the offline cache lookup. Defaults to false. */
  noCache?: boolean;
}

function hashString(input: string): string {
  let h = 5381;
  for (let i = 0; i < input.length; i++) {
    h = ((h << 5) + h) ^ input.charCodeAt(i);
  }
  return (h >>> 0).toString(36);
}

async function readIndex(): Promise<string[]> {
  try {
    const raw = await AsyncStorage.getItem(CACHE_INDEX_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw) as unknown;
    return Array.isArray(parsed) ? (parsed as string[]) : [];
  } catch {
    return [];
  }
}

async function writeIndex(idx: string[]): Promise<void> {
  try {
    await AsyncStorage.setItem(CACHE_INDEX_KEY, JSON.stringify(idx));
  } catch {
    // ignore
  }
}

async function readCache(key: string): Promise<string | null> {
  try {
    return await AsyncStorage.getItem(CACHE_PREFIX + key);
  } catch {
    return null;
  }
}

async function writeCache(key: string, value: string): Promise<void> {
  try {
    await AsyncStorage.setItem(CACHE_PREFIX + key, value);
    const idx = await readIndex();
    const filtered = idx.filter((k) => k !== key);
    filtered.push(key);
    while (filtered.length > MAX_CACHE_ENTRIES) {
      const evict = filtered.shift();
      if (evict) {
        try {
          await AsyncStorage.removeItem(CACHE_PREFIX + evict);
        } catch {
          // ignore
        }
      }
    }
    await writeIndex(filtered);
  } catch {
    // ignore
  }
}

export async function clearPollinationsCache(): Promise<void> {
  const idx = await readIndex();
  for (const k of idx) {
    try {
      await AsyncStorage.removeItem(CACHE_PREFIX + k);
    } catch {
      // ignore
    }
  }
  await writeIndex([]);
}

export async function getCacheStats(): Promise<{ entries: number }> {
  const idx = await readIndex();
  return { entries: idx.length };
}

export async function pollinate(
  messages: ChatMessage[],
  opts: PollinationsOptions = {},
): Promise<string> {
  const model = opts.model ?? "openai-fast";
  const cacheKey = hashString(JSON.stringify({ model, messages }));

  const body = {
    model,
    messages,
    temperature: opts.temperature ?? 0.7,
    private: true,
  };

  try {
    const res = await fetch(TEXT_ENDPOINT, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(body),
      signal: opts.signal,
    });

    if (!res.ok) {
      const txt = await res.text().catch(() => "");
      throw new Error(`Pollinations error ${res.status}: ${txt.slice(0, 200)}`);
    }

    const json = (await res.json()) as {
      choices?: { message?: { content?: string } }[];
    };
    const content = json.choices?.[0]?.message?.content;
    if (!content) throw new Error("Empty response from Pollinations");
    void writeCache(cacheKey, content);
    return content;
  } catch (err) {
    if (!opts.noCache) {
      const cached = await readCache(cacheKey);
      if (cached) {
        return (
          cached +
          "\n\n_(Served from offline cache — network was unavailable.)_"
        );
      }
    }
    throw err;
  }
}

export async function pingPollinations(signal?: AbortSignal): Promise<boolean> {
  try {
    const res = await fetch(PING_ENDPOINT, { signal });
    return res.ok;
  } catch {
    return false;
  }
}

import AsyncStorage from "@react-native-async-storage/async-storage";

const PREFIX = "agent-studio:";

export async function loadJSON<T>(key: string, fallback: T): Promise<T> {
  try {
    const raw = await AsyncStorage.getItem(PREFIX + key);
    if (!raw) return fallback;
    return JSON.parse(raw) as T;
  } catch {
    return fallback;
  }
}

export async function saveJSON<T>(key: string, value: T): Promise<void> {
  try {
    await AsyncStorage.setItem(PREFIX + key, JSON.stringify(value));
  } catch {
    // ignore
  }
}

export async function clearAll(): Promise<void> {
  try {
    const keys = await AsyncStorage.getAllKeys();
    const ours = keys.filter((k) => k.startsWith(PREFIX));
    await AsyncStorage.multiRemove(ours);
  } catch {
    // ignore
  }
}

